BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-j-q1', '4. ディープラーニングの概要',
   '入力が負のとき出力を常に0にするReLUに対し、負のときもごくわずかな傾き（例えば0.01倍）を持たせることで、dying ReLU（ノードが二度と更新されなくなる現象）を防ごうとする活性化関数はどれか。',
   NULL::text,
   '["Leaky ReLU", "シグモイド関数", "ソフトマックス関数", "恒等関数"]',
   0, '[0]', 'single',
   '{"asked":"負の側にわずかな傾きを持たせてdying ReLUを防ぐ活性化関数を選ぶ問題。","why_asked":"ReLU系の弱点（dying ReLU）とその素朴な対策はセットで問われやすい定番論点。","kid":"ReLUは「マイナスの入力は全部0にする」という関数だけど、0にしてしまうとそのノードは二度と目を覚まさなくなることがある。Leaky ReLUは「マイナスでも完全に0にはせず、ほんの少しだけ通してあげる」関数。少しでも信号が流れていれば、そのノードはまだ調整のしようがある。","eg":"たとえるなら、ReLUは「マイナスの意見は完全にシャットアウトする会議」。Leaky ReLUは「マイナスの意見も声量を1%だけ残して聞く会議」。声が完全にゼロだと、その人はもう発言のしようがなくなる。","terms":[["ReLU","入力が負なら0、正ならそのまま通す活性化関数。負の側の勾配は常に0"],["dying ReLU","ReLUのノードが常に負の入力しか受け取らなくなり、勾配が0のまま二度と重みが更新されなくなる現象"],["Leaky ReLU","負の側にも小さな傾き（例:0.01）を残したReLUの改良版"]],"think":"dying ReLUの原因は「負の側の勾配がちょうど0になること」にある。勾配が0だと、誤差逆伝播で運ばれてくる情報がそこで完全に止まってしまう。Leaky ReLUは負の側の傾きを0ではなくわずかな正の値にすることで、たとえ入力が負でも勾配がゼロにならず、重みの更新が止まらないようにしている。","vs":"PReLU（学習可能な傾き）と混同しやすいが、Leaky ReLUの傾きはあらかじめ決めた固定値である点が違う。","opt":["正解。負の側にもわずかな傾きを残すことで勾配を完全には0にせず、dying ReLUを防ぐ。","シグモイド関数は出力を0〜1に押し込む関数で、dying ReLU対策として設計されたものではない。","ソフトマックス関数は複数の出力を確率分布に変換する関数で、多クラス分類の出力層に使うもの。","恒等関数は入力をそのまま出力するだけの関数で、回帰の出力層に使われる。負の側の傾き調整とは無関係。"]}'),

  ('g-kentei-j-q2', '4. ディープラーニングの概要',
   'Leaky ReLUでは負の側の傾きをあらかじめ固定値として決めておくが、その傾きも学習によって自動的に決めさせる活性化関数はどれか。',
   NULL::text,
   '["PReLU（Parametric ReLU）", "ソフトプラス関数", "ハードスウィッシュ", "マックスアウト"]',
   0, '[0]', 'single',
   '{"asked":"負の側の傾きを学習で決める活性化関数を選ぶ問題。","why_asked":"Leaky ReLUとPReLUは名前も仕組みも似ており、「傾きが固定か学習か」という一点の違いを取り違えやすい。","kid":"Leaky ReLUは「マイナスの傾きは0.01と決め打ち」だけど、PReLUは「そのマイナスの傾き自体をちょうどいい値になるまで学習で調整する」もの。傾きの大きさもパラメータの一つとして一緒に育てていくイメージ。","eg":"たとえるなら、Leaky ReLUは「声量を1%と決めて固定した会議」。PReLUは「その声量のパーセンテージ自体を、会議を重ねるうちにちょうどいい値へ調整していく会議」。","terms":[["PReLU","Parametric ReLUの略。直訳は「パラメータ化された・ReLU」。負の側の傾きを学習可能なパラメータにしたReLUの改良版"],["Leaky ReLU","負の側の傾きをあらかじめ決めた固定値にするReLUの改良版"]],"think":"「傾きが固定値か、学習で決まる値か」で区別する。Leaky ReLUは人があらかじめ0.01のような値を決めて渡すだけ。PReLUはその傾きを重みと同じように誤差逆伝播で更新していくので、データに合わせて最適な傾きが自動で見つかる。","vs":"Leaky ReLUと混同しやすいが、Leaky ReLUの傾きは学習中ずっと固定のまま変わらない点が違う。","opt":["正解。負の側の傾きを固定値ではなく学習可能なパラメータとして持つ活性化関数。","ソフトプラス関数はReLUをなめらかにした関数で、負の側の傾きを学習するパラメータは持たない。","ハードスウィッシュは区分線形で近似したスウィッシュ系の活性化関数で、傾きを学習パラメータとして持つ設計ではない。","マックスアウトは複数の線形変換の最大値を取る活性化関数で、負の側の傾きを1つのパラメータとして学習する仕組みとは異なる。"]}'),

  ('g-kentei-j-q3', '4. ディープラーニングの概要',
   '負の入力に対して0に飽和するのではなく、なめらかに一定のマイナスの値へ近づいていく活性化関数で、出力の平均が0に近くなりやすいという特徴を持つものはどれか。',
   NULL::text,
   '["ELU（Exponential Linear Unit）", "ReLU", "ソフトマックス関数", "シグモイド関数"]',
   0, '[0]', 'single',
   '{"asked":"負の側がなめらかに飽和し、出力の平均が0に近づく活性化関数を選ぶ問題。","why_asked":"ReLU系の中でも「出力の平均を0に近づける工夫」という切り口はG検定で見落とされがちな細かい違い。","kid":"ReLUは負の入力を問答無用で0にするけど、ELUは「負の入力ほど、なだらかな坂を下るようにマイナスの一定値に近づいていく」形をしている。出力にマイナスの値も混ざるぶん、全体の平均が0に近くなりやすい。","eg":"たとえるなら、ReLUは「マイナスの意見はすべて無視して0点にする採点」。ELUは「マイナスの意見にも、行き過ぎない範囲でマイナス点をなだらかに付ける採点」。マイナス点があるぶん、全体の平均点が0に寄りやすい。","terms":[["ELU","Exponential Linear Unitの略。直訳は「指数・線形・ユニット」。負の側を指数関数でなめらかに飽和させる活性化関数"],["出力の平均が0に近い","層に入ってくる値の偏りが減り、学習が安定しやすくなるとされる性質"]],"think":"ReLUは負を一律0にするため出力の平均は必ず0以上に偏る。ELUは負の入力に対して「なめらかに一定のマイナス値へ近づく」曲線を使うことで、出力にマイナス側の値も混ざり、平均が0に近づきやすくなる。この「平均が0に近い」性質が学習を安定させると説明される。","vs":"ReLUと混同しやすいが、ReLUの負の側は完全な水平線（常に0）で角があるのに対し、ELUの負の側はなめらかな曲線で一定値に近づく点が違う。","opt":["正解。負の側がなめらかに一定のマイナス値へ飽和し、出力の平均を0に近づけやすい活性化関数。","ReLUは負の入力を一律0にするだけで、なめらかな飽和やマイナス側の出力は持たない。","ソフトマックス関数は複数の出力をまとめて確率分布に変換する関数で、1つの入力を変換する活性化関数とは役割が異なる。","シグモイド関数は出力が0〜1の範囲に限られ、マイナスの値を出すことはない。"]}'),

  ('g-kentei-j-q4', '4. ディープラーニングの概要',
   'Transformerを使ったモデルで、ReLUの代わりによく使われる活性化関数で、入力の値が大きいほど「そのまま通す」確率が高く、小さいほど「遮断する」確率が高くなるようになめらかに変化する関数はどれか。',
   NULL::text,
   '["GELU（Gaussian Error Linear Unit）", "Leaky ReLU", "ソフトマックス関数", "恒等関数"]',
   0, '[0]', 'single',
   '{"asked":"Transformer系でよく使われる、確率的な門のようになめらかに変化する活性化関数を選ぶ問題。","why_asked":"BERTやGPTなど有名なモデルの内部で採用されており、ReLU一辺倒ではないという最新動向を押さえているか問う定番論点。","kid":"ReLUは「0より大きいか小さいか」でスパッと通す・通さないを決めるカクカクした関数。GELUは「値が大きいほど通りやすく、小さいほど通りにくい」というのを、角のないなめらかな坂で表現した関数。まるで、値の大きさに応じて開き具合が変わる自動ドアのようなイメージ。","eg":"たとえるなら、ReLUは「境界線を越えたら即入場、越えなければ即却下」という警備員。GELUは「値が大きいほど入場を許可する確率が上がっていく」という、なめらかに判断基準を変える警備員。","terms":[["GELU","Gaussian Error Linear Unitの略。直訳は「ガウス・誤差・線形・ユニット」。正規分布の累積分布関数を使い、入力の値に応じてなめらかに通す/遮断する活性化関数"],["ReLU","0を境にカクッと折れ曲がる、角のある活性化関数"]],"think":"見分け方は「境目がカクッと折れ曲がっているか、なめらかな曲線か」。ReLUは0のところで角ができるが、GELUはその周辺がなめらかに変化する。この「なめらかさ」がTransformer系のモデルで学習を安定させやすいとされ、BERTやGPTなど多くの大規模言語モデルで採用されている。","vs":"Swish/SiLU（x×sigmoid(x)）と形がよく似ているが、GELUは正規分布の性質を使って定義されている点で由来が異なる。","opt":["正解。入力の値に応じてなめらかに通す/遮断する確率的な門のように振る舞い、Transformer系でよく使われる。","Leaky ReLUは負の側にわずかな傾きを持たせるだけで、0付近の折れ曲がりはReLUと同じくカクッとしている。","ソフトマックス関数は複数の出力をまとめて確率分布にする関数で、1つの値をなめらかに変換する活性化関数とは役割が異なる。","恒等関数は入力をそのまま出力するだけで、値の大きさに応じた確率的な通す/遮断するという性質は持たない。"]}'),

  ('g-kentei-j-q5', '4. ディープラーニングの概要',
   '入力xに対して「x × シグモイド関数(x)」という式で表され、自分自身の値でゲート（門）を作る自己ゲート型の活性化関数はどれか。',
   NULL::text,
   '["Swish（SiLU）", "ソフトプラス関数", "マックスアウト", "ハードシグモイド"]',
   0, '[0]', 'single',
   '{"asked":"x×シグモイド(x)という式で定義される自己ゲート型の活性化関数を選ぶ問題。","why_asked":"数式そのものを覚えているかを直接問う、定義暗記型の頻出パターン。","kid":"Swishは「自分の値」と「自分の値をシグモイド関数に通した0〜1の値（ゲート）」を掛け算する関数。値が大きいほどゲートが開き気味（1に近い）で、値が小さいほどゲートが閉じ気味（0に近い）になる。自分で自分の通り具合を決めているようなイメージ。","eg":"たとえるなら、Swishは「自分の勢いが強いほど、自分で扉を大きく開ける」自動ドア。扉の開き具合（シグモイド）を自分自身の勢い（x）で決めている。","terms":[["Swish","x×σ(x)（xとシグモイド関数σ(x)の積）で定義される活性化関数。SiLU（Sigmoid Linear Unit）とも呼ばれる"],["自己ゲート","入力自身の値を使って、自分自身の通り方（ゲート）を制御する仕組み"]],"think":"数式「x×σ(x)」を思い出せるかがすべて。σ(x)はシグモイド関数で0〜1の値を返すので、Swishはxに0〜1の重みを掛けているとみなせる。xが大きい正の値ならσ(x)が1に近づきほぼxがそのまま出て、xが大きな負の値ならσ(x)が0に近づき出力も0に近づく、という滑らかな挙動になる。","vs":"GELUと形が似ているが、Swishはシグモイド関数を使った式、GELUは正規分布の累積分布関数を使った式で、由来となる数式が異なる。","opt":["正解。x×シグモイド(x)という式で、自分自身の値でゲートを作る活性化関数。","ソフトプラス関数はlog(1+e^x)という式で表され、シグモイド関数との掛け算は使わない。","マックスアウトは複数の線形変換の最大値を取る関数で、シグモイド関数を使う定義ではない。","ハードシグモイドはシグモイド関数を区分線形（折れ線）で近似したもので、シグモイド関数そのものとの掛け算ではない。"]}'),

  ('g-kentei-j-q6', '4. ディープラーニングの概要',
   'ReLU関数(max(0, x))を、0付近で折れ曲がらないようになめらかにした関数で、log(1 + e^x)という式で表されるものはどれか。',
   NULL::text,
   '["ソフトプラス関数", "ソフトマックス関数", "シグモイド関数", "恒等関数"]',
   0, '[0]', 'single',
   '{"asked":"log(1+e^x)という式で表されるReLUのなめらか版を選ぶ問題。","why_asked":"名前が似ているソフトプラスとソフトマックスを取り違えやすく、定番の引っかけになる。","kid":"ReLUは0のところでカクッと折れ曲がるが、ソフトプラス関数はその折れ曲がりを丸くなめらかにした形をしている。式で書くと log(1+e^x) というだけで、やっていることは「ReLUをなめらかにする」こと。","eg":"たとえるなら、ReLUは折り紙を一箇所でパキッと折った形。ソフトプラス関数は同じ場所を、丸みを持たせてなだらかに曲げた形。","terms":[["ソフトプラス関数","log(1+e^x)で表される、ReLUをなめらかにした活性化関数"],["ソフトマックス関数","複数の値を合計1の確率分布に変換する、多クラス分類の出力層で使う関数（別物）"]],"think":"名前の「ソフト◯◯」につられて、複数の出力を確率分布にする「ソフトマックス関数」と混同しないこと。ソフトプラスはあくまで1つの入力に対して1つの出力を返す活性化関数で、ReLUの角を取ってなめらかにしただけのもの。","vs":"名前が似ているソフトマックス関数と混同しやすいが、ソフトマックスは複数の値をまとめて確率分布に変換する関数であり、1入力1出力のソフトプラスとは別物。","opt":["正解。log(1+e^x)で表され、ReLUをなめらかにした活性化関数。","ソフトマックス関数は複数の出力を合計1になる確率分布に変換する関数で、log(1+e^x)という式ではない。","シグモイド関数は1/(1+e^-x)で表され、出力が0〜1の範囲に収まる関数で式が異なる。","恒等関数は入力をそのまま出力するだけの関数で、log(1+e^x)のような変換は行わない。"]}'),

  ('g-kentei-j-q7', '4. ディープラーニングの概要',
   '複数の線形変換の結果を計算し、その中の最大値を出力とすることで、ReLUやLeaky ReLUを特別な場合として含む、より一般的な活性化関数はどれか。',
   NULL::text,
   '["マックスアウト（Maxout）", "ソフトマックス関数", "GELU", "バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"複数の線形変換の最大値を取ることでReLU系を一般化した活性化関数を選ぶ問題。","why_asked":"「活性化関数自体を学習で作る」という発想はG検定であまり触れられないが、ReLU系のまとめとして出題価値がある。","kid":"普通の活性化関数は「1つの計算式」だけを使うが、マックスアウトは「複数の計算式（線形変換）」を用意しておいて、その中で一番大きい値を採用する。式の組み合わせ次第で、ReLUのような形もLeaky ReLUのような形も作り出せる、いわば「形が変えられる活性化関数」。","eg":"たとえるなら、普通の活性化関数は「決まった1つの物差しで測る」やり方。マックスアウトは「何本もの物差しで測っておいて、一番大きい目盛りを採用する」やり方。物差しの本数や向きを変えれば、いろいろな測り方の形を再現できる。","terms":[["Maxout","複数の線形変換を計算し、その最大値を出力とする活性化関数。パラメータの数はReLU系より増える"],["ReLU","0とxの最大値を取る、Maxoutの特別な場合とみなせる活性化関数"]],"think":"「複数の線形変換」「その最大値を採用」という2つのキーワードで判断する。線形変換を2本用意し、一方を「常に0」、もう一方を「x」に設定すればReLUと同じ形が再現できる、というのがMaxoutがReLUを含む一般化と言われる理由。","vs":"ソフトマックス関数と名前が似ているが、ソフトマックスは複数の出力を確率分布に変換する関数で、線形変換の最大値を取る仕組みとは異なる。","opt":["正解。複数の線形変換の最大値を出力とし、ReLUやLeaky ReLUを特別な場合として含む一般化された活性化関数。","ソフトマックス関数は複数の出力の合計を1にそろえる関数で、最大値だけを採用する仕組みではない。","GELUは正規分布の性質を使った1つの数式で定義される活性化関数で、複数の線形変換から最大値を選ぶ仕組みではない。","バッチ正規化は活性化関数ではなく、層に入ってくる値のばらつきをそろえる正規化の手法。"]}'),

  ('g-kentei-j-q8', '4. ディープラーニングの概要',
   'スマートフォンなど計算資源の限られた環境向けの軽量なモデルで、シグモイド関数やSwishを、なめらかな曲線ではなく折れ線（区分線形）で近似することで計算を軽くした活性化関数はどれか。',
   NULL::text,
   '["ハードシグモイド／ハードスウィッシュ", "ELU", "ソフトプラス関数", "PReLU"]',
   0, '[0]', 'single',
   '{"asked":"モバイル向けに曲線を折れ線で近似して軽量化した活性化関数を選ぶ問題。","why_asked":"モデルの軽量化という切り口とセットで、活性化関数レベルの工夫も問われることがある。","kid":"シグモイド関数やSwishは指数の計算(e^x)が入っていて、計算に少し手間がかかる。ハードシグモイド／ハードスウィッシュは、その曲線をまっすぐな線をいくつかつなげた折れ線でおおまかに真似することで、スマホのような非力な機械でも素早く計算できるようにしたもの。","eg":"たとえるなら、なめらかな坂道（シグモイド）を、階段のように角ばった斜面（折れ線）で大まかに再現するイメージ。見た目は少しカクカクするが、上り下りにかかる労力（計算量）はぐっと減る。","terms":[["ハードシグモイド","シグモイド関数のなめらかな曲線を、折れ線（区分線形）で近似したもの"],["ハードスウィッシュ","Swish関数を折れ線で近似したもの。MobileNetV3など軽量モデルで使われる"]],"think":"「軽量化」「モバイル」「折れ線で近似」というキーワードが出てきたら、ハードシグモイド／ハードスウィッシュを疑う。指数関数の計算を四則演算だけの折れ線に置き換えることで、計算コストを下げつつ元の曲線に近い形を保つ、という工夫。","vs":"PReLUと混同しやすいが、PReLUは負の側の傾きを学習するのが目的で、計算コストを下げるための折れ線近似ではない。","opt":["正解。シグモイド関数やSwishを折れ線で近似し、計算コストを下げた軽量な活性化関数。","ELUは負の側をなめらかな指数関数で飽和させる活性化関数で、計算を軽くするための折れ線近似ではない。","ソフトプラス関数はReLUをなめらかにする関数で、逆に指数関数の計算が必要になり計算量は増える方向。","PReLUは負の側の傾きを学習可能にする工夫であり、計算コストの削減を目的とした折れ線近似とは異なる。"]}'),

  ('g-kentei-j-q9', '4. ディープラーニングの概要',
   'シグモイド関数の傾き（微分値）の最大値は0.25であるのに対し、tanh関数の傾きの最大値は1である。この違いが、層の深いネットワークで一般に意味することとして最も適切なものはどれか。',
   NULL::text,
   '["tanh関数の方が、逆伝播のたびに勾配が縮みにくく、勾配消失がやや起きにくいとされる", "シグモイド関数の方が、逆伝播のたびに勾配が縮みにくく、勾配消失がやや起きにくいとされる", "傾きの最大値は勾配消失の起きやすさとは無関係で、どちらを使っても差はない", "tanh関数は傾きの最大値が1より大きいため、シグモイド関数よりも勾配爆発を起こしやすい"]',
   0, '[0]', 'single',
   '{"asked":"シグモイドとtanhの傾きの最大値の違いが、勾配消失の起きやすさにどう関わるかを問う問題。","why_asked":"「シグモイドは勾配消失を起こしやすい」という結論は覚えていても、tanhとの数値の比較まで説明できるかを試す一段深い論点。","kid":"逆伝播では、各層の傾き（微分値）を何度も掛け算していく。シグモイドの傾きはどんなに大きくても0.25までしかなく、0.25を何度も掛け算するとどんどん小さくなっていく。tanhの傾きは最大1なので、シグモイドよりは値が縮みにくい。","eg":"たとえるなら、シグモイドは「1回ごとに必ず4分の1以下に薄まるジュース」、tanhは「最大でも薄まらずそのまま運べることがあるジュース」。何度も継ぎ足していくと、薄まりやすいシグモイドの方が早く味（勾配）が消えてしまう。","terms":[["勾配消失","逆伝播で勾配が層を伝わるうちにどんどん小さくなり、入力に近い層の重みがほとんど更新されなくなる現象"],["tanh関数","出力を-1〜1の範囲に変換する活性化関数。傾きの最大値は1でシグモイドより大きい"]],"think":"逆伝播の勾配は各層の傾きの掛け算で表される。掛け算する数がすべて1未満なら、掛け合わせるほど値は小さくなっていく。シグモイドの傾きの上限0.25はtanhの上限1より小さいため、同じ深さの層を通すとシグモイドの方がより急激に勾配が縮み、勾配消失が起きやすいとされる。","vs":"「tanhなら勾配消失が絶対に起きない」という誤解に注意。tanhも傾きの最大値が1であって、多くの場所ではそれより小さいため、層がとても深ければやはり勾配消失は起こり得る。あくまで「シグモイドよりはやや起きにくい」という程度の違い。","opt":["正解。傾きの最大値がシグモイドの0.25よりtanhの1の方が大きいため、tanhの方が勾配が縮みにくいとされる。","傾きの最大値が小さいシグモイドの方が、掛け算を重ねるほど勾配が早く縮みやすく、この記述は逆になっている。","傾きの最大値の違いは掛け算を重ねたときの縮み方に直結するため、無関係とは言えない。","tanhの傾きの最大値は1であり、1より大きいという記述が誤り。1を超えないため勾配爆発の主因にはなりにくい。"]}'),

  ('g-kentei-j-q10', '4. ディープラーニングの概要',
   '1枚の画像が「犬」「猫」「鳥」のどれか1つに必ず分類される多クラス分類のタスクと、1枚の画像に「犬」「屋外」「昼間」のように複数のラベルが同時に当てはまりうるマルチラベル分類のタスクで、出力層に使う活性化関数の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["多クラス分類にはソフトマックス関数、マルチラベル分類には各ラベルごとのシグモイド関数を使う", "どちらのタスクにもソフトマックス関数を使う。合計が1になる方が扱いやすいため", "多クラス分類には各ラベルごとのシグモイド関数、マルチラベル分類にはソフトマックス関数を使う", "どちらのタスクにも恒等関数を使い、しきい値で後から分類を決める"]',
   0, '[0]', 'single',
   '{"asked":"排他的な多クラス分類とマルチラベル分類で、出力層の活性化関数をどう使い分けるかを問う問題。","why_asked":"ソフトマックスとシグモイドの使い分けは「多クラスかどうか」だけで覚えがちだが、マルチラベルという条件が絡むと迷いやすい。","kid":"「犬か猫か鳥か、どれか1つだけ」を選ぶときは、全部足すと1になるソフトマックス関数がぴったり。でも「犬でもあり屋外でもあり昼間でもある」というふうに複数当てはまってよいときは、それぞれのラベルを独立に「当てはまる確率0〜1」で判定するシグモイド関数を、ラベルの数だけ並べて使う。","eg":"たとえるなら、ソフトマックスは「クラスの人気投票で1位だけを選ぶ」やり方（票の合計は100%）。シグモイドをラベルごとに使うのは「それぞれの項目に対して、当てはまるか当てはまらないかを別々にYES/NOで判定していく」やり方。","terms":[["ソフトマックス関数","複数の出力の合計が1になるように変換する関数。排他的な多クラス分類の出力層に向く"],["マルチラベル分類","1つのデータに複数のラベルが同時に当てはまりうる分類タスク"]],"think":"見分け方は「正解が同時に複数ありうるか」。同時に1つしか正解がない（排他的）ならソフトマックスで「どれか1つに票を集中させる」形にする。複数同時に正解でありうるなら、ラベルごとに独立したシグモイドで「当てはまるかどうか」を別々に判定する方が理にかなっている。","vs":"「多クラス分類=ソフトマックス」だけを覚えていると、マルチラベル分類にもソフトマックスを使ってしまいがちだが、ソフトマックスは合計が1に固定されるため、複数のラベルに同時に高い確率を与えることが構造上できない。","opt":["正解。排他的な多クラス分類にはソフトマックス、複数同時に正解がありうるマルチラベル分類にはラベルごとのシグモイドを使う。","マルチラベル分類にソフトマックスを使うと合計が1に制約され、複数のラベルに同時に高い確率を与えにくくなる。","多クラス分類と多ラベル分類で使う関数が入れ替わっており、説明が逆になっている。","恒等関数は出力を0〜1に押し込まないため、確率としてしきい値判定するのに適さない。"]}'),

  ('g-kentei-j-q11', '4. ディープラーニングの概要',
   'あるモデルの出力層の活性化関数を選ぶ場面を3つ挙げる。(1)住宅価格をそのまま予測する回帰、(2)「合格」か「不合格」かを判定する二値分類、(3)手書き数字0〜9のどれか1つを当てる多クラス分類。それぞれに使う活性化関数の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["(1)恒等関数 (2)シグモイド関数 (3)ソフトマックス関数", "(1)ソフトマックス関数 (2)恒等関数 (3)シグモイド関数", "(1)シグモイド関数 (2)ソフトマックス関数 (3)恒等関数", "(1)恒等関数 (2)恒等関数 (3)恒等関数（すべて同じでよい）"]',
   0, '[0]', 'single',
   '{"asked":"回帰・二値分類・多クラス分類のそれぞれに適した出力層の活性化関数を選ぶ問題。","why_asked":"出力層の活性化関数選びは実務でもよく間違える基本だが、3パターンをまとめて問われると迷いやすい。","kid":"(1)価格そのものの数字を当てたいなら、変換せずそのまま出す恒等関数。(2)YES/NOの2択なら、0〜1の「確率」に変換してくれるシグモイド関数。(3)10個の候補から1つを選ぶなら、全部の確率を足すと1になるソフトマックス関数。","eg":"たとえるなら、(1)は「値段をそのまま答える」、(2)は「合格の確率は何%か答える」、(3)は「0〜9の候補それぞれに何%の自信があるか、合計100%になるように答える」というイメージ。","terms":[["恒等関数","入力をそのまま出力する関数。回帰の出力層に使う"],["シグモイド関数","出力を0〜1の確率に変換する関数。二値分類の出力層に使う"],["ソフトマックス関数","複数の出力の合計を1にそろえる関数。多クラス分類の出力層に使う"]],"think":"出力層の活性化関数は「出したい答えの形」から逆算する。数値そのものが欲しいなら変換しない（恒等関数）。YES/NOの確率が欲しいなら0〜1に押し込む（シグモイド）。複数候補から1つを選ぶ確率分布が欲しいなら合計を1にそろえる（ソフトマックス）。","vs":"二値分類と多クラス分類でシグモイドとソフトマックスを取り違えやすいが、二値分類はソフトマックスで代用しても数学的にはシグモイドと等価になることが知られている一方、G検定の定番の使い分けとしてはシグモイド=二値、ソフトマックス=多クラスで覚えておく。","opt":["正解。回帰には恒等関数、二値分類にはシグモイド関数、多クラス分類にはソフトマックス関数を使う。","回帰と二値分類の関数が入れ替わっており、価格をそのまま出したい回帰にソフトマックスは合わない。","二値分類と多クラス分類の関数が入れ替わっており、10クラスの分類に恒等関数では確率が得られない。","3つとも恒等関数にすると、二値分類や多クラス分類で確率という扱いやすい形の出力が得られなくなる。"]}'),

  ('g-kentei-j-q12', '4. ディープラーニングの概要',
   'シグモイド関数 σ(x) = 1 / (1 + e^-x) について、x = 0 のときの出力の値はいくつか。',
   NULL::text,
   '["0.5", "0", "1", "0.25"]',
   0, '[0]', 'single',
   '{"asked":"シグモイド関数にx=0を代入したときの出力値を計算する問題。","why_asked":"式を覚えているだけでなく、実際に数字を当てはめて計算できるかを試す基本の計算問題。","kid":"シグモイド関数は「1 ÷ (1 + e の -x 乗)」という式。x に 0 を入れると、e の 0 乗は必ず1になるので、式は「1 ÷ (1 + 1)」つまり「1 ÷ 2」になる。答えは 0.5。","eg":"たとえるなら、シグモイド関数はどんな数を入れても0〜1の間に収める「変換マシン」。x=0というちょうど真ん中の入力を入れると、変換結果もちょうど真ん中の0.5になる、というイメージ。","terms":[["シグモイド関数","1/(1+e^-x)で表され、出力を0〜1の範囲に収める活性化関数"],["e（ネイピア数）","約2.718…という決まった値の定数。e^0は必ず1になる"]],"calc":{"steps":["問題: σ(0) = 1 / (1 + e^-0) を計算する","ステップ1: 指数の部分を計算する。-0 は 0 なので、e^-0 は e^0 のこと","ステップ2: e の 0 乗は、どんな数の0乗も1になるのと同じで、必ず1になる。e^0 = 1","ステップ3: 分母を計算する。1 + e^0 = 1 + 1 = 2","ステップ4: 割り算する。1 ÷ 2 = 0.5","答え: σ(0) = 0.5"],"formula":"σ(x) = 1 / (1 + e^-x) に x=0 を代入 → σ(0) = 1/(1+e^0) = 1/(1+1) = 0.5"},"think":"式の中の未知数はxだけなので、x=0を代入して四則演算するだけで解ける。e^0=1という指数のルールさえ知っていれば、あとは1+1=2、1÷2=0.5という小学校レベルの計算で終わる。","vs":"e^-x を「eに-xを掛ける」と勘違いしないこと。e^-x は「eの-x乗」という指数の計算であり、x=0なら常に1になる。","opt":["正解。e^0=1なので、1/(1+1)=0.5になる。","0になるのはxが非常に大きなマイナスの値に近づいたときの極限であり、x=0のときの値ではない。","1になるのはxが非常に大きなプラスの値に近づいたときの極限であり、x=0のときの値ではない。","0.25はシグモイド関数の微分（傾き）の最大値であり、シグモイド関数そのものの値ではない。"]}'),

  ('g-kentei-j-q13', '4. ディープラーニングの概要',
   'ソフトマックス関数に、2つの入力値としてまったく同じ値（例えば両方とも3）を入れると、それぞれのクラスに割り当てられる確率はどうなるか。',
   NULL::text,
   '["両方とも0.5になり、2つのクラスに均等に確率が割り振られる", "入力値が大きいほうがそのまま確率になり、片方が1、もう片方が0になる", "入力値の符号によって、片方が必ず0.9以上になる", "計算ができず、エラーになる"]',
   0, '[0]', 'single',
   '{"asked":"ソフトマックス関数に同じ値を2つ入れたときの出力の確率を求める問題。","why_asked":"数式を丸暗記するのではなく、「入力の差が0のとき出力はどうなるか」という性質から理解できているかを試す問題。","kid":"ソフトマックス関数は、入力の値が大きいクラスほど高い確率を割り振る関数。でも今回は2つとも同じ大きさ（3と3）なので、どちらが特に優れているという差がない。差がないなら、確率も仲良く半分ずつ、つまり0.5と0.5になる。","eg":"たとえるなら、2人のかけっこのタイムがまったく同じだったら、「どちらが優勝か」を決める根拠がないので、優勝確率を50%ずつに分け合うのが自然、というイメージ。","terms":[["ソフトマックス関数","各クラスの値の大きさに応じて、合計が1になる確率を割り振る関数。値が大きいクラスほど高い確率になる"]],"calc":{"steps":["問題: 入力値が z1=3, z2=3 のとき、それぞれのソフトマックス出力を考える","ステップ1: ソフトマックスは e^z1 と e^z2 を計算し、その比率で確率を分ける仕組み","ステップ2: z1=z2=3なので、e^z1 と e^z2 はまったく同じ値になる（e^3 = e^3）","ステップ3: 同じ値どうしの比率は1:1、つまりちょうど半分ずつになる","ステップ4: 合計は必ず1になる決まりなので、半分ずつなら0.5と0.5","答え: 両方とも0.5になる"],"formula":"z1=z2 のとき e^z1=e^z2 となり、確率は e^z1/(e^z1+e^z2) = e^z2/(e^z1+e^z2) = 0.5 ずつになる"},"think":"ソフトマックスの出力は「入力の相対的な大きさの差」で決まる。差がまったくない（同じ値）ということは、どちらのクラスも同じだけ「らしい」ということなので、確率も均等に0.5ずつに分かれる。入力の絶対的な大きさ（3という数値そのもの）は、差がない限り最終的な確率の偏りには影響しない。","vs":"「入力値がそのまま確率になる」という誤解に注意。ソフトマックスは入力の値を直接確率として使うのではなく、指数関数を通した比率で確率を作る。","opt":["正解。入力値の差がないため、確率も均等に0.5ずつに分かれる。","ソフトマックスは指数関数を使った比率で確率を作るため、入力値がそのまま0や1になるわけではない。","入力値がどちらも正の3であり、符号による偏りが生まれる状況ではない。","ソフトマックス関数はどんな実数の入力に対しても必ず確率を計算でき、エラーにはならない。"]}'),

  ('g-kentei-j-q14', '4. ディープラーニングの概要',
   '外れ値を含むデータで回帰モデルを学習させたい。誤差が小さい範囲では二乗誤差のように、誤差が大きい範囲では絶対誤差のように振る舞うことで、外れ値の影響を受けにくくした誤差関数はどれか。',
   NULL::text,
   '["Huber損失", "交差エントロピー損失", "Hinge損失", "KLダイバージェンス"]',
   0, '[0]', 'single',
   '{"asked":"外れ値に強い、二乗誤差と絶対誤差のハイブリッドのような誤差関数を選ぶ問題。","why_asked":"MSEの弱点（外れ値に弱い）を補う具体策として、Huber損失は実務でもよく使われる定番の工夫。","kid":"二乗誤差（MSE）は、大きくずれた1件の外れ値があると、その誤差を2乗するのでとても大きな値になってしまい、学習がそこに引っ張られすぎる。Huber損失は「誤差が小さいうちは普通に2乗で測るけど、誤差が大きくなりすぎたら2乗をやめて、ただの差の大きさ（絶対値）で測る」という切り替えをする。","eg":"たとえるなら、普段の遅刻は「遅れた分数を2乗して罰金」だけど、あまりに遅刻がひどいときは2乗にせず「遅れた分数そのまま」で罰金にする、というルール。ひどい遅刻の罰金が青天井にならないようにする工夫。","terms":[["Huber損失","誤差が小さい範囲は二乗誤差、大きい範囲は絶対誤差のように振る舞う誤差関数。外れ値に強い"],["MSE（平均二乗誤差）","誤差を2乗して平均する誤差関数。外れ値があると値が大きく引っ張られやすい"]],"think":"「外れ値に強い誤差関数」という切り口が出たら、Huber損失を思い出す。二乗誤差は外れ値をより重く罰しすぎる、絶対誤差は常に一定のペースでしか罰しない、という両者の弱点を、誤差の大きさに応じて使い分けることで補っている。","vs":"MSE（平均二乗誤差）と混同しやすいが、MSEは常に二乗のまま計算し続け、外れ値ほど極端に大きな誤差を返してしまう点が違う。","opt":["正解。誤差の大きさに応じて二乗誤差と絶対誤差を使い分け、外れ値に強くした誤差関数。","交差エントロピー損失は分類問題の確率のずれを測る誤差関数で、外れ値対策の回帰用誤差関数ではない。","Hinge損失はSVMなどで使われる、マージンを意識した分類用の誤差関数で、回帰の外れ値対策とは異なる。","KLダイバージェンスは2つの確率分布の隔たりを測る指標で、回帰の外れ値対策の誤差関数ではない。"]}'),

  ('g-kentei-j-q15', '4. ディープラーニングの概要',
   'サポートベクターマシン(SVM)などで使われる誤差関数で、正しく分類できているデータでも、境界線からの余白（マージン）が十分でなければ罰則を与える誤差関数はどれか。',
   NULL::text,
   '["Hinge損失", "MSE（平均二乗誤差）", "Huber損失", "コサイン類似度"]',
   0, '[0]', 'single',
   '{"asked":"正しく分類していても余白が足りなければ罰則を与える誤差関数を選ぶ問題。","why_asked":"「正解したら誤差ゼロ」という直感に反する性質を持つため、他の誤差関数との違いを問う価値がある。","kid":"普通の誤差関数は「正解できていれば誤差はほぼ0」だけど、Hinge損失は「正解はしているけど、境界線ギリギリでしか正解できていない」場合にも、まだ少し罰則を与える。余裕を持って正解してほしい、という気持ちを誤差に込めている。","eg":"たとえるなら、テストで「合格ラインぎりぎりで滑り込んだ」人にも、「もっと余裕を持って合格してほしい」と言って追加の宿題（罰則）を出すイメージ。不合格ではないのに、まだ改善を促す。","terms":[["Hinge損失","正しく分類していても、境界線からの余白（マージン）が不十分なら罰則を与える誤差関数。SVMで使われる"],["マージン","分類の境界線から、最も近いデータ点までの余白の広さ"]],"think":"「正解=誤差0」ではない誤差関数、という性質がHinge損失を見分ける決め手。他の多くの誤差関数（MSEや交差エントロピーなど）は完全に正解すれば誤差が0や非常に小さい値に近づくが、Hinge損失は正解していてもマージンが狭いままなら罰則が残る設計になっている。","vs":"交差エントロピー損失と混同しやすいが、交差エントロピーは確率のずれそのものを測るのに対し、Hinge損失は「境界からどれだけ離れて正解しているか」という余白を測る点が違う。","opt":["正解。正しく分類していても余白が不十分なら罰則を与える、マージンを意識した誤差関数。","MSEは予測値と正解値の差を2乗して測る誤差関数で、マージンという概念は使わない。","Huber損失は外れ値に強い回帰用の誤差関数で、分類のマージンを扱う誤差関数ではない。","コサイン類似度は2つのベクトルの向きの近さを測る指標で、誤差関数として直接使われるものではない。"]}'),

  ('g-kentei-j-q16', '4. ディープラーニングの概要',
   '正常データに比べて異常データが極端に少ない不均衡なデータで分類モデルを学習させたい。簡単に正解できる（多数派の）データの損失を意図的に小さく抑え、難しい（少数派の）データに学習の重心を置かせる誤差関数はどれか。',
   NULL::text,
   '["Focal Loss", "MSE（平均二乗誤差）", "Hinge損失", "L2正則化"]',
   0, '[0]', 'single',
   '{"asked":"クラス不均衡なデータで、簡単な例の損失を抑え難しい例を重視させる誤差関数を選ぶ問題。","why_asked":"クラス不均衡はG検定でも実践的な課題として扱われやすく、対策の1つとして誤差関数の工夫を知っているか問う。","kid":"データの99%が「正常」で1%だけ「異常」というような場合、ふつうに学習すると「とりあえず全部正常と答えておけば当たりやすい」というサボりが起きやすい。Focal Lossは「もう簡単に正解できているデータ」の罰則をわざと軽くして、「まだ間違えやすいデータ」にもっと注意を向けさせる工夫。","eg":"たとえるなら、テストの復習で「もう完璧に解ける問題」を何度も解き直すのはもったいないので、その配点を下げて、「まだ苦手な問題」の配点を相対的に上げる、というイメージ。","terms":[["Focal Loss","簡単な例の損失を小さく抑え、難しい例（少数派クラスなど）に学習の重心を置かせる誤差関数"],["クラス不均衡","分類したいクラスの数（データ件数）が大きく偏っている状態"]],"think":"「クラス不均衡」「簡単な例より難しい例を重視」というキーワードの組み合わせが出たらFocal Lossを疑う。通常の交差エントロピー損失をベースに、すでに高い確率で正解できている例には小さな重み、まだ自信のない例には大きな重みを掛けることで、少数派クラスの学習が多数派に埋もれないようにする。","vs":"ラベルスムージングと混同しやすいが、ラベルスムージングは正解ラベルの値自体を緩めるのに対し、Focal Lossは損失の大きさに例ごとの重みを掛ける点が違う。","opt":["正解。簡単な例の損失を抑え、難しい例に学習の重心を置かせることでクラス不均衡に対応する誤差関数。","MSEは回帰でよく使う誤差関数で、クラスごとの難易度に応じた重み付けは行わない。","Hinge損失はマージンを意識した分類用の誤差関数で、クラス不均衡への重み付けを主目的とした設計ではない。","L2正則化は誤差関数そのものではなく、重みの大きさにペナルティを課して過学習を防ぐ手法。"]}'),

  ('g-kentei-j-q17', '4. ディープラーニングの概要',
   '分類モデルの正解ラベルを「正解クラスは100%、それ以外は0%」とせず、「正解クラスは90%、残りのクラスにも少しずつ確率を分ける」というように緩めることで、モデルが自信過剰になりすぎるのを防ぐ工夫はどれか。',
   NULL::text,
   '["ラベルスムージング", "データ拡張", "アーリーストッピング", "バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"正解ラベルを100%ではなく少し緩めることで自信過剰を防ぐ工夫を選ぶ問題。","why_asked":"正則化の一種としてラベル側に手を加える発想はG検定でも見落とされがちだが、生成AIの学習でも使われる実践的な工夫。","kid":"ふつうモデルには「正解は100%こっち、他は0%」と教えるけど、これだと「絶対に正解！」と自信満々になりすぎて、少し違うデータが来たときに柔軟に対応できなくなることがある。ラベルスムージングは「正解は90%くらいにしておいて、残り10%は他のクラスにも分けておく」というふうに、わざと少しだけ曖昧さを残す工夫。","eg":"たとえるなら、先生が「これは絶対100%Aさんの答えが正しい」と教えるのではなく、「Aさんの答えが一番近いけど、他の考え方にも少しだけ理があるよ」と教えることで、生徒が頭ごなしに自信を持ちすぎないようにするイメージ。","terms":[["ラベルスムージング","正解ラベルの値を100%ではなく少し緩めて、モデルの過信を防ぐ正則化の一種"],["過学習","訓練データに合わせすぎて、新しいデータへの対応力が落ちる現象"]],"think":"「正解ラベルの値自体をいじる」という点が他の正則化（ドロップアウトやL2正則化など）との違い。ドロップアウトはノードを無効化し、L2正則化は重みの大きさを抑えるが、ラベルスムージングは教師データの「正解」の与え方そのものを緩めることで、モデルが極端な確信度を持つのを防ぐ。","vs":"Focal Lossと混同しやすいが、Focal Lossは損失の大きさに例ごとの重みを掛けるのに対し、ラベルスムージングは正解ラベルの値そのものを緩める点が違う。","opt":["正解。正解ラベルの値を100%ではなく緩めることで、モデルの自信過剰を防ぐ工夫。","データ拡張は画像の回転や反転などでデータの水増しを行う手法で、ラベルの値そのものを緩める工夫ではない。","アーリーストッピングは検証誤差が悪化し始めた時点で学習を打ち切る過学習対策で、ラベルの値の変更ではない。","バッチ正規化は層に入ってくる値のばらつきをそろえる手法で、ラベルの値とは関係しない。"]}'),

  ('g-kentei-j-q18', '4. ディープラーニングの概要',
   '「猫」「犬」「鳥」のどれか1つだけが正解になる排他的な多クラス分類で使う誤差関数と、1枚の画像に複数のタグ（例えば「屋外」と「昼間」）が同時に正解になりうるマルチラベル分類で使う誤差関数の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["多クラス分類にはカテゴリカル交差エントロピー、マルチラベル分類にはラベルごとの2値交差エントロピー", "どちらのタスクにもカテゴリカル交差エントロピーを使う", "多クラス分類にはラベルごとの2値交差エントロピー、マルチラベル分類にはカテゴリカル交差エントロピー", "どちらのタスクにもHuber損失を使う"]',
   0, '[0]', 'single',
   '{"asked":"排他的な多クラス分類とマルチラベル分類で、誤差関数をどう使い分けるかを問う問題。","why_asked":"出力層の活性化関数（ソフトマックス vs シグモイド）とセットで、対応する誤差関数の使い分けも理解しているか問う。","kid":"「どれか1つだけ正解」の問題では、ソフトマックスで作った確率分布と正解ラベルとのズレを、カテゴリカル交差エントロピーでまとめて1つの誤差として測る。「複数同時に正解」の問題では、ラベルごとに別々の2択（当てはまる/当てはまらない）として、それぞれに2値交差エントロピーを計算して足し合わせる。","eg":"たとえるなら、多クラス分類は「クラス全員の中から1人だけ委員長を選ぶ」ようなテストの採点。マルチラベル分類は「この生徒は真面目か？運動が得意か？絵が上手か？」という項目それぞれに別々にYES/NOで採点していくテスト。","terms":[["カテゴリカル交差エントロピー","ソフトマックスの出力と1つの正解クラスとのズレをまとめて測る誤差関数"],["2値交差エントロピー","シグモイドの出力（当てはまる確率）と1つのラベルの正解・不正解とのズレを測る誤差関数"]],"think":"出力層の活性化関数と誤差関数はセットで考える。ソフトマックス（合計が1、排他的）にはカテゴリカル交差エントロピーが対応し、ラベルごとのシグモイド（それぞれ独立に0〜1）にはラベルごとの2値交差エントロピーが対応する。","vs":"「交差エントロピーはどれも同じ」と一括りにしがちだが、対象が「1つの正解を選ぶ確率分布」か「複数の独立した2択」かで、使うべき交差エントロピーの種類が変わる。","opt":["正解。排他的な多クラス分類にはカテゴリカル交差エントロピー、マルチラベル分類にはラベルごとの2値交差エントロピーを使う。","マルチラベル分類にカテゴリカル交差エントロピーを使うと、複数のラベルに同時に高い値を与える設計と噛み合わない。","多クラス分類と多ラベル分類の誤差関数が入れ替わっており、説明が逆になっている。","Huber損失は回帰の外れ値対策の誤差関数で、分類タスクの誤差関数として使うものではない。"]}'),

  ('g-kentei-j-q19', '4. ディープラーニングの概要',
   '顔認証のように「同じ人物の顔どうしは近づけ、違う人物の顔どうしは遠ざける」ように埋め込みベクトルを学習させたい。アンカー・正例・負例の3つの組を使って学習する誤差関数はどれか。',
   NULL::text,
   '["Triplet Loss", "MSE（平均二乗誤差）", "交差エントロピー損失", "Hinge損失"]',
   0, '[0]', 'single',
   '{"asked":"アンカー・正例・負例の3つ組で埋め込みを学習する誤差関数を選ぶ問題。","why_asked":"顔認証など「距離を学習する」タスクの代表的な誤差関数で、通常の分類用誤差関数と考え方が異なる点を問う。","kid":"Triplet Lossは3枚の写真を1セットにして学習する。「基準になる写真（アンカー）」「同じ人の別の写真（正例）」「別人の写真（負例）」を用意し、「アンカーと正例の距離は近づけて、アンカーと負例の距離は遠ざける」ように学習していく。","eg":"たとえるなら、1人の生徒（アンカー）を基準に、「仲良しの友達（正例）とはもっと近い席に座らせ、あまり関係のないクラスメート（負例）とはもっと離れた席に座らせる」ように、少しずつ座席（埋め込み空間での位置）を調整していくイメージ。","terms":[["Triplet Loss","アンカー・正例・負例の3つ組を使い、正例を近づけ負例を遠ざけるように学習する誤差関数"],["埋め込み(embedding)","データを、意味の近さが距離として表現される数値のベクトルに変換したもの"]],"think":"「3つ組（アンカー・正例・負例）」というキーワードがTriplet Lossを見分ける決め手。通常の交差エントロピー損失やMSEは「1つの正解」との比較だが、Triplet Lossは「近づけたい相手」と「遠ざけたい相手」の両方を同時に扱う点が特徴的。","vs":"通常の交差エントロピー損失と混同しやすいが、交差エントロピーは「決まったクラスに属する確率」を測るのに対し、Triplet Lossは「2つの埋め込みベクトルどうしの距離」を測る点が違う。","opt":["正解。アンカー・正例・負例の3つ組を使い、正例を近づけ負例を遠ざけるように学習する誤差関数。","MSEは予測値と正解値の差を2乗して測る誤差関数で、3つ組の距離を扱う設計ではない。","交差エントロピー損失は決まったクラスへの分類確率のズレを測る誤差関数で、距離学習の3つ組とは異なる。","Hinge損失は分類のマージンを意識した誤差関数で、アンカー・正例・負例の3つ組を直接扱う設計ではない。"]}'),

  ('g-kentei-j-q20', '4. ディープラーニングの概要',
   '2クラス分類で、正解クラスに対するモデルの予測確率が0.5だった場合と0.9だった場合を比べると、交差エントロピー損失（-log(予測確率)）はどうなるか。',
   NULL::text,
   '["予測確率0.5のときの方が、0.9のときより損失が大きくなる", "予測確率0.9のときの方が、0.5のときより損失が大きくなる", "予測確率が何であっても、交差エントロピー損失は常に同じ値になる", "予測確率0.5のとき損失は0になり、0.9のときは負の値になる"]',
   0, '[0]', 'single',
   '{"asked":"予測確率が0.5のときと0.9のときで交差エントロピー損失の大小を比較する問題。","why_asked":"「予測確率が正解に近いほど損失は小さくなる」という交差エントロピーの基本性質を、実際の数値感覚で確認させる問題。","kid":"交差エントロピー損失は「-log(正解クラスの予測確率)」で計算される。予測確率が1に近い（自信を持って正解している）ほど損失は小さく、予測確率が低い（自信がない、もしくは間違えている）ほど損失は大きくなる。0.9は0.5より1に近いので、0.9のときの方が損失は小さい。","eg":"たとえるなら、正解を「90%の自信で言い当てた」人と「50%の自信でなんとなく言った」人がいたら、後者の方が「もっと自信を持て」という指摘（損失）を強く受ける、というイメージ。","terms":[["交差エントロピー損失","-log(正解クラスの予測確率)で計算される、分類モデルの誤差関数"],["log（対数）","ここでは自然対数。1に近い値のlogは0に近づき、0に近い値のlogはマイナスに大きく振れる"]],"calc":{"steps":["問題: 予測確率0.5のときと0.9のときの-log(予測確率)を比べる","ステップ1: logは「1に近いほど0に近く、0に近いほどマイナスに大きく振れる」という性質を持つ","ステップ2: 0.9は1にかなり近いので、log(0.9)は0に近い小さいマイナスの値になる","ステップ3: 0.5は1から離れているので、log(0.5)は0.9のときよりもっと大きいマイナスの値になる","ステップ4: 損失は-log(予測確率)、つまりマイナスを取って符号を反転させたもの。log(0.5)の方がマイナスとして大きいので、-log(0.5)は-log(0.9)より大きいプラスの値になる","答え: 予測確率0.5のときの方が損失は大きい"],"formula":"損失 = -log(予測確率)。予測確率が1に近いほど-log(予測確率)は0に近づき、0に近いほど大きくなる"},"think":"交差エントロピー損失の式-log(p)の性質として、pが1に近づくほど損失は0に近づき、pが0に近づくほど損失は際限なく大きくなる、という単調な関係を押さえておけば、具体的な対数の値を暗算しなくても大小関係だけは判断できる。","vs":"「確率が高いほど損失も大きくなる」と直感的に逆に覚えてしまう人がいるが、損失は「間違っている度合い」を表すので、自信を持って正解しているほど損失は小さくなるのが正しい。","opt":["正解。予測確率が1から遠い0.5の方が、1に近い0.9より損失は大きくなる。","予測確率が1に近いほど交差エントロピー損失は小さくなるため、この記述は逆になっている。","予測確率によって-log(予測確率)の値は変化するため、常に同じ値にはならない。","予測確率が1未満である限り-log(予測確率)は正の値になり、0や負の値にはならない。"]}'),

  ('g-kentei-j-q21', '4. ディープラーニングの概要',
   '出現する頻度が低い特徴量（例えば自然言語処理でめったに出てこない単語）ほど大きく更新し、頻繁に出てくる特徴量ほど更新の歩幅を小さくしていく、パラメータごとに学習率を自動調整する最適化手法はどれか。',
   NULL::text,
   '["AdaGrad", "モメンタム法（Momentum）", "確率的勾配降下法（SGD）", "重み減衰（weight decay）"]',
   0, '[0]', 'single',
   '{"asked":"出現頻度が低い特徴量ほど大きく更新する、パラメータごとに学習率を自動調整する最適化手法を選ぶ問題。","why_asked":"「なぜこの手法が生まれたか」という動機（疎な特徴量への対応）まで理解しているかを問う。","kid":"ふつうの勾配降下法は、どのパラメータにも同じ歩幅（学習率）で更新をかける。AdaGradは「これまであまり動いてこなかったパラメータには大きめの歩幅」「もう十分動いてきたパラメータには小さめの歩幅」というふうに、パラメータごとに歩幅を自動で変えていく。たまにしか出てこない単語のパラメータは、他に比べて更新のチャンスが少ないぶん、1回あたりの歩幅を大きくしてあげるイメージ。","eg":"たとえるなら、練習量が少ない生徒には1回の授業でしっかり多めに教え、すでに練習を重ねた生徒には少しの復習で済ませる、という生徒ごとにペース配分を変える先生のようなもの。","terms":[["AdaGrad","各パラメータのこれまでの勾配の2乗を累積し、動いてきた量に応じて学習率を自動調整する最適化手法"],["疎な特徴量","めったに出現しない、多くがゼロで埋まっているような特徴量"]],"think":"「疎な特徴量」「出現頻度で学習率を変える」というキーワードが出たらAdaGradを疑う。これまでの勾配の2乗を累積しておき、累積が大きい（よく更新されてきた）パラメータほど学習率を下げ、累積が小さい（あまり更新されてこなかった）パラメータほど学習率を高く保つ、という設計になっている。","vs":"モメンタム法と混同しやすいが、モメンタムは「更新の勢い（方向）」を引き継ぐ工夫であり、パラメータごとに学習率そのものを変える工夫ではない。","opt":["正解。パラメータごとの勾配の累積量に応じて学習率を自動調整し、出現頻度が低い特徴量ほど大きく更新する。","モメンタム法は過去の更新方向の勢いを引き継ぐ工夫で、パラメータごとの学習率調整とは別の発想。","確率的勾配降下法は全パラメータに同じ学習率を使う基本形で、パラメータごとの自動調整は行わない。","重み減衰は重みの大きさにペナルティを課す正則化の手法で、学習率の自動調整とは異なる。"]}'),

  ('g-kentei-j-q22', '4. ディープラーニングの概要',
   'AdaGradは学習を続けるうちに勾配の2乗を累積し続けるため、学習の終盤で学習率が下がりすぎて更新がほとんど止まってしまう弱点がある。この累積を「これまでの全部」ではなく「直近の勾配を重視する指数移動平均」に置き換えることで、この弱点を解決した最適化手法はどれか。',
   NULL::text,
   '["RMSProp", "AdaGrad", "確率的勾配降下法（SGD）", "L2正則化"]',
   0, '[0]', 'single',
   '{"asked":"AdaGradの学習率が下がりすぎる弱点を、直近の勾配を重視する形に改良した最適化手法を選ぶ問題。","why_asked":"AdaGrad→RMSProp→Adamという最適化手法の発展の流れの中で、RMSPropがどの弱点をどう直したかというピンポイントの理解を問う。","kid":"AdaGradは勾配の2乗を「学習が始まってから今までの全部」をひたすら足し続けるので、学習が長引くほど累積がどんどん大きくなり、最終的にはほとんど動けなくなってしまう。RMSPropは「全部を足す」のではなく「最近の勾配ほど重視し、昔の勾配は少しずつ忘れていく」という平均の取り方に変えることで、学習率が下がりすぎるのを防いだ。","eg":"たとえるなら、AdaGradは「これまでの人生で走った距離を全部足し合わせて、疲労度を計算する」やり方。走れば走るほど疲労度は増える一方で、いずれ動けなくなる。RMSPropは「直近1週間の走った距離だけで疲労度を計算する」やり方に変え、昔の疲労を引きずらないようにしたイメージ。","terms":[["RMSProp","勾配の2乗の累積を、直近を重視する指数移動平均に置き換えた最適化手法。AdaGradの学習率低下問題を緩和する"],["指数移動平均","直近のデータほど大きな重みを持たせ、昔のデータの影響を徐々に小さくしていく平均の取り方"]],"think":"「AdaGradの弱点をどう直したか」という因果関係で覚える。弱点は「累積し続けて学習率が下がりすぎる」こと。RMSPropの対策は「全部の累積」を「直近重視の移動平均」に変えることで、昔の勾配の影響を薄め、学習率が際限なく下がり続けるのを防いだ点にある。","vs":"AdaGradと混同しやすいが、AdaGradは勾配の2乗を学習開始からすべて累積し続けるのに対し、RMSPropは直近を重視した移動平均を使う点が違う。","opt":["正解。勾配の2乗の累積を直近重視の指数移動平均に置き換え、AdaGradの学習率低下問題を緩和した手法。","AdaGradは本問で説明されている弱点を持つ側の手法であり、それを解決した手法として選ぶのは誤り。","確率的勾配降下法は全パラメータに同じ学習率を使う基本形で、勾配の累積による学習率調整自体を行わない。","L2正則化は重みの大きさにペナルティを課す手法で、学習率の調整方法とは無関係。"]}'),

  ('g-kentei-j-q23', '4. ディープラーニングの概要',
   'Adamにネステロフのモメンタム（先読みして勢いを計算する工夫）を組み合わせた最適化手法はどれか。',
   NULL::text,
   '["Nadam", "AdaGrad", "RMSProp", "AMSGrad"]',
   0, '[0]', 'single',
   '{"asked":"AdamにNesterovモメンタムを組み合わせた最適化手法の名前を選ぶ問題。","why_asked":"Adamの発展形はいくつもあり、それぞれ「何と何を組み合わせたか」という由来を区別できるかを問う。","kid":"モメンタムには「そのまま今の勢いで進む」ふつうのモメンタムと、「もう少し先まで進んだ場所を覗いてから勢いを調整する」ネステロフのモメンタムという工夫がある。NadamはAdamのモメンタム部分を、このネステロフ版に置き換えたもの。名前も「Nesterov」＋「Adam」で「Nadam」となっている。","eg":"たとえるなら、ふつうのモメンタムは「今の勢いのまま突き進む」走り方。ネステロフのモメンタムは「その勢いで少し先まで行ってみてから、必要なら軌道修正する」走り方。Nadamは、Adamの走り方にこの「先読み」を組み込んだもの。","terms":[["Nadam","Nesterov（ネステロフ）とAdamを組み合わせた最適化手法"],["ネステロフのモメンタム","現在の勢いで少し先まで進んだ地点の勾配を使って、更新方向を調整するモメンタムの改良版"]],"think":"名前の由来から覚えるのが一番早い。「Nadam」は「Nesterov」＋「Adam」の合成語で、Adamの持つモメンタムの部分を、より先読み性能の高いネステロフのモメンタムに差し替えたもの、という成り立ちを押さえておけば選べる。","vs":"AMSGradと混同しやすいが、AMSGradはAdamの収束性の問題（過去の最大値を使うよう修正）を直したものであり、ネステロフのモメンタムを組み込んだものではない。","opt":["正解。Adamのモメンタム部分をネステロフのモメンタムに置き換えた最適化手法。","AdaGradはAdamより前に提案された、パラメータごとに学習率を調整する手法で、ネステロフのモメンタムの組み込みとは無関係。","RMSPropはAdamの構成要素の1つだが、ネステロフのモメンタムを組み合わせたものではない。","AMSGradはAdamの収束性の問題を修正した手法で、ネステロフのモメンタムを組み込んだものではない。"]}'),

  ('g-kentei-j-q24', '4. ディープラーニングの概要',
   'Adamは特定の条件下でうまく収束しないことが理論的に指摘されている。この問題を、過去に見た勾配の2乗の「最大値」を使うように改良することで修正しようとした最適化手法はどれか。',
   NULL::text,
   '["AMSGrad", "Nadam", "AdaGrad", "モメンタム法（Momentum）"]',
   0, '[0]', 'single',
   '{"asked":"Adamの収束性の問題を、過去の勾配の2乗の最大値を使うことで修正した最適化手法を選ぶ問題。","why_asked":"「Adamは万能ではなく理論的な弱点も指摘されている」という一段深い視点を持っているかを問う。","kid":"Adamは実務ではよく使われる便利な最適化手法だけど、理論的には「ある特殊な状況ではうまく最適な答えにたどり着けないことがある」と指摘されている。AMSGradは、勾配の2乗を平均する代わりに「これまで見た中で一番大きかった値」を覚えておいて使うことで、この収束の問題を直そうとした手法。","eg":"たとえるなら、Adamは「直近の状況だけを見て毎回歩幅を決める」やり方だけど、時々の状況次第では判断がブレてしまう。AMSGradは「これまでで一番慎重だった歩幅（最大値）を覚えておき、それより無闇に大きくは歩かない」というルールを足して、判断のブレを抑えたイメージ。","terms":[["AMSGrad","Adamの収束性の問題を、過去の勾配の2乗の最大値を使うことで修正しようとした最適化手法"],["収束","最適化を繰り返すうちに、パラメータが最適な値（または近い値）に落ち着いていくこと"]],"think":"「Adamの弱点（理論的な収束性の問題）」「過去の最大値を使う」という2つのキーワードでAMSGradを判断する。Adamは勾配の2乗を指数移動平均で滑らかにするが、AMSGradはその移動平均が減ってしまう場面で、過去の最大値を下回らないように保つことで、理論上の収束性を改善しようとしている。","vs":"Nadamと混同しやすいが、Nadamはネステロフのモメンタムを組み込む改良であり、収束性の理論的な問題を直接修正するものではない。","opt":["正解。過去の勾配の2乗の最大値を使うことで、Adamの理論的な収束性の問題を修正しようとした手法。","Nadamはネステロフのモメンタムを組み込んだAdamの改良で、収束性の理論的な修正が主目的ではない。","AdaGradはAdamより前に提案された手法で、Adamの収束性の問題を修正するために考案されたものではない。","モメンタム法は更新の勢いを引き継ぐ基本的な工夫で、Adamの収束性の理論的な問題への対処とは異なる。"]}'),

  ('g-kentei-j-q25', '4. ディープラーニングの概要',
   '学習の最初は小さな学習率から始め、数エポックかけて徐々に本来の学習率まで引き上げていく工夫を何と呼ぶか。学習初期の重みがまだ不安定な段階で、大きすぎる学習率によって発散してしまうのを防ぐ目的で使われる。',
   NULL::text,
   '["学習率のウォームアップ", "アーリーストッピング", "コサインアニーリング", "データ拡張"]',
   0, '[0]', 'single',
   '{"asked":"学習初期に小さい学習率から徐々に引き上げる工夫の名前を選ぶ問題。","why_asked":"学習率のスケジューリングは近年の大規模モデルの学習で欠かせない実務的な工夫であり、名前と目的を対応づけて覚えているか問う。","kid":"重みをランダムな値で初期化した学習の最初の段階は、まだどちらへ進めばいいのかも不安定な状態。ここでいきなり大きな学習率を使うと、勢い余って発散してしまうことがある。ウォームアップは、最初は小さな歩幅で慎重に様子を見ながら進み、少し落ち着いてきたら本来の歩幅まで少しずつ広げていく工夫。","eg":"たとえるなら、準備運動をせずにいきなり全力疾走すると転んでしまうので、最初はゆっくり歩き出し、体が温まってきたら徐々にスピードを上げていく、というウォーミングアップのイメージ。","terms":[["学習率のウォームアップ","学習の最初は小さな学習率から始め、徐々に本来の学習率まで引き上げていく工夫"],["発散","誤差が下がるどころか、更新のたびにどんどん大きくなってしまう現象"]],"think":"「学習の最初」「小さい学習率から徐々に上げる」という組み合わせがウォームアップを見分ける決め手。コサインアニーリングなど他のスケジューリング手法は「学習率を下げていく」方向の工夫であり、最初に学習率を上げていく段階を指す言葉ではない点に注意。","vs":"コサインアニーリングと混同しやすいが、コサインアニーリングは学習が進むにつれて学習率をなめらかに下げていく手法で、ウォームアップの「最初に上げる」段階とは向きが逆。実際には両者を組み合わせて使うことも多い。","opt":["正解。学習の最初は小さな学習率から始め、徐々に本来の学習率まで引き上げていく工夫。","アーリーストッピングは検証誤差の悪化を見て学習を打ち切る過学習対策で、学習率の調整とは異なる。","コサインアニーリングは学習率をコサインカーブに沿って下げていくスケジューリング手法で、最初に上げていく工夫ではない。","データ拡張は画像の回転や反転などでデータを水増しする手法で、学習率の調整とは無関係。"]}'),

  ('g-kentei-j-q26', '4. ディープラーニングの概要',
   '学習率を、エポックが進むにつれてコサインカーブ（余弦曲線）に沿ってなめらかに減衰させていく学習率スケジューリング手法はどれか。',
   NULL::text,
   '["コサインアニーリング", "学習率のウォームアップ", "アーリーストッピング", "バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"コサインカーブに沿って学習率を減衰させるスケジューリング手法を選ぶ問題。","why_asked":"学習率を一定の割合で減らす単純な方法との違いを、名前の由来（コサインカーブ）から理解しているか問う。","kid":"学習率をだんだん小さくしていくとき、直線的にまっすぐ減らすのではなく、コサイン（余弦）という数学のなめらかな波のカーブに沿って減らしていくやり方がコサインアニーリング。最初はゆっくり減り、中盤で減るスピードが速くなり、終盤はまたゆっくり0に近づいていく、というなめらかな減り方をする。","eg":"たとえるなら、ジェットコースターが急に止まるのではなく、なめらかなカーブを描きながら速度を落として、最後にゆっくり停止するようなイメージ。学習率もこのなめらかなカーブに沿って落ち着かせていく。","terms":[["コサインアニーリング","学習率をコサインカーブに沿ってなめらかに減衰させるスケジューリング手法"],["アニーリング（焼きなまし）","金属を高温からゆっくり冷やすことに由来する言葉で、値を少しずつなめらかに落ち着かせていく操作全般を指す"]],"think":"「コサイン」という名前がそのままカーブの形（余弦関数の形）を表している。学習率を一定量ずつ直線的に下げる単純な方法とは違い、コサインアニーリングは最初と最後はゆるやかに、中盤で急に下がるという波のような減り方をする点が特徴。","vs":"ウォームアップと混同しやすいが、ウォームアップは学習率を「上げていく」最初の段階を指し、コサインアニーリングは学習が進むにつれて学習率を「下げていく」段階を指す。両者は組み合わせて使われることが多い。","opt":["正解。学習率をコサインカーブに沿ってなめらかに減衰させるスケジューリング手法。","学習率のウォームアップは学習の最初に学習率を徐々に上げていく工夫で、下げていく本手法とは向きが逆。","アーリーストッピングは検証誤差の悪化を見て学習を打ち切る過学習対策で、学習率のスケジューリングとは異なる。","バッチ正規化は層に入ってくる値のばらつきをそろえる手法で、学習率のスケジューリングとは無関係。"]}'),

  ('g-kentei-j-q27', '4. ディープラーニングの概要',
   'バッチサイズを大きくすると、1回の更新で使うデータが増えるぶん勾配の推定が安定するため、学習率も比例して大きくできるという経験則を活かした調整として最も適切なものはどれか。',
   NULL::text,
   '["バッチサイズを大きくした分だけ、学習率も大きくして更新の歩幅を確保する", "バッチサイズを大きくしたら、学習率は必ず0に近づけて更新をほぼ止める", "バッチサイズと学習率は無関係なので、バッチサイズを変えても学習率は一切調整しない", "バッチサイズを大きくするほど、学習率は反比例して極端に小さくしなければならない"]',
   0, '[0]', 'single',
   '{"asked":"バッチサイズを大きくしたときの学習率の調整の考え方を選ぶ問題。","why_asked":"大規模な分散学習でバッチサイズを増やす際の実践的な工夫として知られている経験則。","kid":"バッチサイズが大きいと、1回の更新で見るデータの数が増えるので、勾配の平均がより安定した（ブレの少ない）値になる。安定しているなら、1回あたりの歩幅（学習率）をもう少し大きくしても暴走しにくいので、学習率もバッチサイズに合わせて大きくする、という考え方。","eg":"たとえるなら、少人数のアンケートより大人数のアンケートの方が結果がブレにくいので、その分「思い切って大きく方針を変える」判断がしやすくなる、というイメージ。データが多く安定しているぶん、思い切った歩幅で進める。","terms":[["バッチサイズ","1回の重み更新で使うデータの件数"],["線形スケーリング則","バッチサイズを何倍かにしたら、学習率もおおよそ同じ倍率で大きくするという経験則"]],"think":"バッチサイズが大きい→勾配の推定が安定する→少々大きな歩幅で進んでも暴走しにくい、という因果関係を押さえる。逆にバッチサイズが小さいと勾配の推定がブレやすいので、学習率を大きくしすぎると発散しやすい。","vs":"「バッチサイズを大きくすると学習が不安定になるから学習率を下げる」という逆の直感を持ちやすいが、実際には勾配の推定が安定する方向に働くため、経験則としては学習率を上げる方向で調整される。","opt":["正解。バッチサイズを大きくして勾配の推定が安定した分、学習率も比例して大きくする経験則。","学習率を0に近づけると更新がほぼ止まり、バッチサイズを大きくした恩恵を活かせなくなる。","バッチサイズと学習率には経験則として比例関係があるとされ、無関係とは言えない。","バッチサイズを大きくすると勾配の推定は安定する方向に働くため、学習率を反比例して極端に下げる根拠にはならない。"]}'),

  ('g-kentei-j-q28', '4. ディープラーニングの概要',
   'ある重みの現在の値は6、その重みに対する勾配は8、学習率は0.25だとする。勾配降下法の更新式「新しい重み = 現在の重み − 学習率 × 勾配」に当てはめると、更新後の重みの値はいくつになるか。',
   NULL::text,
   '["4", "6", "8", "14"]',
   0, '[0]', 'single',
   '{"asked":"具体的な数値を勾配降下法の更新式に当てはめて、更新後の重みを計算する問題。","why_asked":"更新式を暗記しているだけでなく、実際に数値を代入して計算できるかを確認する基本の計算問題。","kid":"更新式は「今の重み − 学習率 × 勾配」というだけの引き算と掛け算。今回は「今の重み6」「勾配8」「学習率0.25」なので、まず学習率×勾配を先に計算してから、それを今の重みから引く。","eg":"たとえるなら、今いる地点（重み6）から、坂の傾きの強さ（勾配8）に歩幅の設定（学習率0.25）を掛けた分だけ、坂を下る方向（マイナス）に進む、というイメージ。","terms":[["勾配降下法","誤差が小さくなる方向（勾配の逆向き）へ重みを少しずつ動かして誤差を減らす最適化の考え方"],["学習率","1回の更新でどれだけ大きく重みを動かすかを決める値"]],"calc":{"steps":["問題: 現在の重み=6、勾配=8、学習率=0.25のとき、新しい重みを求める","ステップ1: 更新式は「新しい重み = 現在の重み − 学習率 × 勾配」","ステップ2: まず学習率×勾配を計算する。0.25 × 8 = 2","ステップ3: 現在の重みからその値を引く。6 − 2 = 4","答え: 新しい重みは4"],"formula":"新しい重み = 6 − (0.25 × 8) = 6 − 2 = 4"},"think":"更新式は「今の重み」から「学習率×勾配」を引くだけの単純な式。掛け算を先に済ませてから引き算をする、という計算の順番さえ守れば、あとは小学校レベルの四則演算で解ける。","vs":"「学習率＋勾配」のように足し算してしまう間違いに注意。更新式はあくまで「学習率×勾配」という掛け算の結果を、現在の重みから引く形になっている。","opt":["正解。6 − (0.25×8) = 6 − 2 = 4。","6は更新前の重みの値であり、更新後の値ではない。","8は勾配の値そのものであり、更新後の重みの値ではない。","6+(0.25×8)=8のように足し算してしまった場合の値で、更新式は引き算であるため誤り。"]}'),

  ('g-kentei-j-q29', '4. ディープラーニングの概要',
   'Adamの更新式に登場する、勾配の移動平均（モメンタム部分）と勾配の2乗の移動平均（RMSProp部分）を、それぞれどれくらいの割合で「直近を重視するか」を決めるハイパーパラメータを一般に何と呼ぶか。',
   NULL::text,
   '["指数移動平均の減衰率（β1, β2）", "学習率（learning rate）", "バッチサイズ", "エポック数"]',
   0, '[0]', 'single',
   '{"asked":"Adamの2つの移動平均それぞれの「直近重視の度合い」を決めるハイパーパラメータの名前を問う問題。","why_asked":"Adam=モメンタム+RMSPropという構造は覚えていても、それぞれの移動平均を調整するハイパーパラメータの存在まで知っているかを問う一段深い論点。","kid":"Adamは「勾配そのものの平均（モメンタム部分）」と「勾配を2乗した値の平均（RMSProp部分）」という2種類の平均を計算している。それぞれの平均で「直近のデータをどれくらい重視するか」を調整するつまみが、β1（ベータ1）とβ2（ベータ2）と呼ばれるハイパーパラメータ。","eg":"たとえるなら、2種類の天気予報（降水量の平均と、降水量のばらつきの平均）を作るときに、それぞれ「直近何日分をどれくらい重視するか」を別々のつまみで調整しているようなイメージ。","terms":[["β1（ベータ1）","勾配そのものの移動平均（モメンタム部分）で、直近をどれくらい重視するかを決めるハイパーパラメータ"],["β2（ベータ2）","勾配の2乗の移動平均（RMSProp部分）で、直近をどれくらい重視するかを決めるハイパーパラメータ"]],"think":"Adam=モメンタム+RMSPropという構造を思い出せれば、「モメンタムの移動平均」と「RMSPropの移動平均」がそれぞれ別の減衰率を持つはずだ、と推測できる。この2つの減衰率を指す記号がβ1とβ2で、一般にβ1=0.9、β2=0.999あたりの値がよく使われる。","vs":"学習率と混同しやすいが、学習率は更新全体の歩幅の大きさを決める値であり、β1・β2は2種類の移動平均それぞれの「直近重視の度合い」を決める、別の役割のハイパーパラメータ。","opt":["正解。勾配の移動平均と勾配の2乗の移動平均、それぞれの直近重視の度合いを決めるハイパーパラメータβ1・β2のこと。","学習率は更新全体の歩幅を決める値で、2種類の移動平均それぞれの減衰率とは別のハイパーパラメータ。","バッチサイズは1回の更新で使うデータの件数を指し、移動平均の減衰率とは無関係。","エポック数は訓練データ全体を何周学習させるかを指し、移動平均の減衰率とは無関係。"]}'),

  ('g-kentei-j-q30', '5. ディープラーニングの要素技術',
   '通常の畳み込みを、「チャネルごとに別々のフィルタで畳み込む処理」と「1×1畳み込みでチャネルをまとめる処理」の2段階に分解することで、計算量とパラメータ数を大きく減らした畳み込みの手法はどれか。MobileNetなどモバイル向けの軽量なモデルで使われる。',
   NULL::text,
   '["Depthwise Separable Convolution（深さ方向分離畳み込み）", "Dilated Convolution（拡張畳み込み）", "Grouped Convolution（グループ畳み込み）", "Transposed Convolution（転置畳み込み）"]',
   0, '[0]', 'single',
   '{"asked":"通常の畳み込みを2段階に分解して軽量化する手法を選ぶ問題。","why_asked":"モバイル向けの軽量モデルの代表的な工夫で、通常の畳み込みとの計算量の違いを理解しているか問う。","kid":"ふつうの畳み込みは、フィルタが全チャネルの情報を一気にまとめて処理する。Depthwise Separable Convolutionは、これを「まずチャネルごとに別々に畳み込む（Depthwise）」「その後1×1畳み込みでチャネル同士をまとめる（Pointwise）」という2段階の作業に分けることで、同じような効果を保ちながら計算の手間をぐっと減らしている。","eg":"たとえるなら、ふつうの畳み込みは「全教科をまとめて1人の先生が一気に採点する」やり方。Depthwise Separable Convolutionは「まず教科ごとに別々の先生が採点し（Depthwise）、その後まとめ役の先生が教科をまたいで総合評価する（Pointwise）」という分業制にして、全体の手間を減らすイメージ。","terms":[["Depthwise Separable Convolution","畳み込みを「チャネルごとの畳み込み」と「1×1畳み込みによるチャネル統合」の2段階に分解した軽量な畳み込み手法"],["1×1畳み込み","空間方向は広げず、チャネル方向の情報だけを混ぜ合わせる畳み込み"]],"think":"「2段階に分解」「軽量化」「モバイル向け」というキーワードの組み合わせがこの手法を見分ける決め手。通常の畳み込みが1回でチャネルと空間の両方を同時に処理するのに対し、この手法はチャネル方向の処理（Depthwise）と空間をまたぐ統合（Pointwise、1×1畳み込み）を分けることでパラメータ数を減らしている。","vs":"Grouped Convolutionと混同しやすいが、Grouped Convolutionはチャネルをいくつかのグループに分けて並列に畳み込む手法で、Depthwise Separableは「チャネルごとに完全に分離してから1×1畳み込みでまとめる」という、より極端な分解になっている。","opt":["正解。チャネルごとの畳み込みと1×1畳み込みの2段階に分解し、計算量とパラメータ数を大きく減らす手法。","Dilated Convolutionはフィルタの間隔を広げて受容野を広げる手法で、2段階への分解による軽量化とは異なる。","Grouped Convolutionはチャネルをグループに分けて並列に畳み込む手法で、チャネルごとに完全分離するDepthwise Separableとは粒度が異なる。","Transposed Convolutionは特徴マップを引き伸ばすアップサンプリングに使う畳み込みで、軽量化を目的とした分解ではない。"]}'),

  ('g-kentei-j-q31', '5. ディープラーニングの要素技術',
   '畳み込みで得られた各チャネルの特徴マップに対し、「どのチャネルが今回の入力にとって重要か」を学習し、その重要度に応じてチャネルごとに重み付け（掛け算）をかける仕組みはどれか。',
   NULL::text,
   '["Squeeze-and-Excitation（SE）ブロック", "スキップ結合（残差接続）", "バッチ正規化", "Global Average Pooling"]',
   0, '[0]', 'single',
   '{"asked":"チャネルごとの重要度を学習して重み付けする注意機構を選ぶ問題。","why_asked":"「空間方向のAttention」だけでなく「チャネル方向の注意機構」もあることを押さえているかを問う、CNN×Attentionの発展的論点。","kid":"CNNの特徴マップにはたくさんのチャネル（フィルタの数だけ）があるけれど、その中には「今回の画像にとって特に役立つチャネル」と「あまり役に立たないチャネル」が混ざっている。SEブロックは、まず各チャネルの情報をぎゅっと1つの数字に集約し（Squeeze）、その数字からチャネルごとの重要度を計算して（Excitation）、重要なチャネルほど強く、そうでないチャネルほど弱く、掛け算で重み付けする仕組み。","eg":"たとえるなら、オーケストラの演奏で、今の曲に合わせて「バイオリンの音量を上げ、ティンパニの音量を少し下げる」というふうに、楽器（チャネル）ごとの音量を曲に合わせて自動調整するミキサーのようなイメージ。","terms":[["Squeeze-and-Excitation（SEブロック）","チャネルごとの重要度を学習し、重み付けするチャネル注意機構"],["チャネル","畳み込みの各フィルタが出力する特徴マップの1枚1枚"]],"think":"「チャネルごとの重要度」「重み付け」という組み合わせがSEブロックを見分ける決め手。Squeeze（各チャネルの情報を1つの数字に要約する）とExcitation（その数字から重要度を計算する）という2段階の処理で、通常の畳み込みだけでは学習しにくいチャネル間の重要度の差を明示的に扱えるようにしている。","vs":"バッチ正規化と混同しやすいが、バッチ正規化は値のばらつきをそろえて学習を安定させる仕組みで、チャネルごとの重要度に応じた重み付けとは目的が異なる。","opt":["正解。各チャネルの重要度を学習し、その重要度に応じてチャネルごとに重み付けする仕組み。","スキップ結合は層を飛び越えて入力を足し込む仕組みで、チャネルごとの重要度による重み付けとは異なる。","バッチ正規化は値のばらつきをそろえて学習を安定させる正規化手法で、重要度に応じた重み付けとは目的が異なる。","Global Average Poolingは特徴マップ全体を1つの平均値に集約するプーリング手法で、チャネルごとの重み付け自体は行わない。"]}'),

  ('g-kentei-j-q32', '5. ディープラーニングの要素技術',
   'ある層の出力を、直後の層だけでなく、それより後ろのすべての層にも直接つなぐことで、層と層の間の接続を非常に密にしたネットワーク構造はどれか。',
   NULL::text,
   '["DenseNet", "ResNet", "Highway Network", "AlexNet"]',
   0, '[0]', 'single',
   '{"asked":"ある層の出力を後続のすべての層に直接つなぐ、密な接続を持つネットワーク構造を選ぶ問題。","why_asked":"ResNetのスキップ結合（隣の層への1本のショートカット）と、DenseNetの「全部につなぐ」という違いを区別できるかを問う。","kid":"ResNetは「ある層の出力を、少し先の層にだけショートカットでつなぐ」構造。DenseNetはそれをもっと徹底して、「ある層の出力を、それより後ろの全部の層に直接つなぐ」という、網の目のように密な接続をしている。","eg":"たとえるなら、ResNetは「1つ前の会議の議事録を、次の会議にだけ手渡す」やり方。DenseNetは「これまでの全部の会議の議事録を、これから開く全部の会議に配る」やり方。情報の流れがずっと密になっている。","terms":[["DenseNet","ある層の出力を、それより後ろのすべての層に直接つなぐ、密な接続を持つネットワーク構造"],["ResNet","層をいくつか飛び越えて入力を足し込むスキップ結合（残差接続）を持つネットワーク構造"]],"think":"「後ろの全部の層につなぐ」という徹底ぶりがDenseNetを見分ける決め手。ResNetのスキップ結合が「1本の近道」を追加するのに対し、DenseNetは各層の出力をそれ以降のすべての層の入力として使い回すため、接続の数そのものが桁違いに多くなる。","vs":"ResNetと混同しやすいが、ResNetは足し算（加算）で情報を伝えるスキップ結合が中心なのに対し、DenseNetは各層の出力をつなぎ合わせる（連結する）形で後続のすべての層に渡す点が違う。","opt":["正解。ある層の出力を、後ろのすべての層に直接つなぐ密な接続を持つネットワーク構造。","ResNetは層をいくつか飛び越えて入力を足し込むスキップ結合が特徴で、後ろの全層に直接つなぐ密な接続ではない。","Highway Networkはゲートで素通しと変換を切り替えるスキップ結合の一種で、後ろの全層への密な接続とは異なる仕組み。","AlexNetは初期の代表的なCNNの構造で、後ろの全層への密な接続という特徴的な仕組みは持たない。"]}'),

  ('g-kentei-j-q33', '5. ディープラーニングの要素技術',
   '層の出力に対して「入力をそのまま素通しするか、それとも変換した値を使うか」をゲート（門）によって学習させながら決める、ResNetより前に提案されたスキップ結合の仕組みはどれか。',
   NULL::text,
   '["Highway Network", "DenseNet", "オートエンコーダ", "バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"素通しと変換の割合をゲートで制御する、ResNet以前のスキップ結合の仕組みを選ぶ問題。","why_asked":"ResNetのスキップ結合の「前身」となる考え方を知っているかという、歴史的な発展の流れを問う論点。","kid":"ResNetのスキップ結合は「入力をそのまま足す」という決まった配合だけど、Highway Networkはその前に考案されたもので、「そのまま通す量」と「変換して使う量」の配合そのものを、ゲートという仕組みで学習して自動調整する。ゲートが開けば入力がそのまま流れ、閉じれば変換された値が使われる、という調整弁のようなもの。","eg":"たとえるなら、水道の蛇口の開き具合（ゲート）を、状況に応じて自動で調整して、「元の水（入力）をそのまま流すか、フィルターを通した水（変換した値）を流すか」の配合を変えるイメージ。","terms":[["Highway Network","入力を素通しするか変換するかの配合をゲートで学習するスキップ結合の仕組み。ResNetの前身とされる"],["ゲート","情報をどれだけ通すかを、学習によって調整する仕組み"]],"think":"「ゲートで配合を調整する」という点がHighway Networkの最大の特徴で、これがResNetの「常に一定の割合で足し込む」というシンプルなスキップ結合の前段階にあたる、という歴史的な流れで理解しておくとよい。","vs":"ResNetと混同しやすいが、ResNetのスキップ結合は入力をそのまま足すだけで配合を調整するゲートを持たないのに対し、Highway Networkはゲートによって素通しの度合いを学習で変えられる点が違う。","opt":["正解。入力を素通しするか変換するかの配合をゲートで学習する、ResNet以前のスキップ結合の仕組み。","DenseNetは後ろのすべての層に直接つなぐ密な接続が特徴で、ゲートによる素通し量の調整とは異なる仕組み。","オートエンコーダは入力を圧縮して復元する構造で、ゲート付きのスキップ結合とは別の概念。","バッチ正規化は値のばらつきをそろえる正規化手法で、素通しと変換の配合を調整するゲートとは異なる。"]}'),

  ('g-kentei-j-q34', '5. ディープラーニングの要素技術',
   'チャネルを複数のグループに分け、それぞれのグループの中だけで畳み込みを行い、最後にグループの結果をまとめるという処理を並列に行う畳み込みの手法はどれか。ResNeXtなどで使われる。',
   NULL::text,
   '["Grouped Convolution（グループ畳み込み）", "Dilated Convolution（拡張畳み込み）", "Global Average Pooling", "1×1畳み込み"]',
   0, '[0]', 'single',
   '{"asked":"チャネルをグループに分けて並列に畳み込む手法を選ぶ問題。","why_asked":"Depthwise Separable Convolution（チャネルを完全に1つずつ分ける）とGrouped Convolution（いくつかのグループにまとめて分ける）の粒度の違いを区別できるかを問う。","kid":"ふつうの畳み込みはすべてのチャネルを1つのフィルタでまとめて処理するけど、Grouped Convolutionはチャネルをいくつかの小さなグループに分けて、グループごとに別々のフィルタで畳み込みを行う。グループの数だけ、並行して小さな畳み込みを走らせているイメージ。","eg":"たとえるなら、クラス全員（全チャネル）を1つの班にしてまとめて作業させるのではなく、いくつかの小さな班に分けて、班ごとに別々の課題（フィルタ）に取り組ませるようなイメージ。","terms":[["Grouped Convolution","チャネルをいくつかのグループに分け、グループごとに独立した畳み込みを並列に行う手法"],["Depthwise Separable Convolution","チャネルを1つずつ完全に分離して畳み込む、Grouped Convolutionをさらに極端にした手法とみなせる"]],"think":"「グループに分ける」という粒度がポイント。チャネルを1つずつ完全に分けるDepthwise Separable Convolutionと、複数チャネルをまとめたグループ単位で分けるGrouped Convolutionは、どちらも計算量を減らす発想は近いが、分割の粒度が異なる。","vs":"Depthwise Separable Convolutionと混同しやすいが、Depthwise Separable Convolutionはチャネルを1つずつに分けるのに対し、Grouped Convolutionは複数チャネルをまとめたグループ単位で分ける点が違う。","opt":["正解。チャネルをいくつかのグループに分け、グループごとに独立した畳み込みを並列に行う手法。","Dilated Convolutionはフィルタの間隔を広げて受容野を広げる手法で、チャネルのグループ分けとは異なる発想。","Global Average Poolingは特徴マップ全体を1つの平均値に集約するプーリング手法で、畳み込みのグループ分けとは異なる。","1×1畳み込みは空間方向を変えずチャネル方向の情報を混ぜ合わせる畳み込みで、チャネルをグループに分ける手法ではない。"]}'),

  ('g-kentei-j-q35', '5. ディープラーニングの要素技術',
   'ネットワークの「深さ（層の数）」「幅（各層のチャネル数）」「解像度（入力画像のサイズ）」の3つを、ばらばらに増やすのではなく、あらかじめ決めた一定の比率でバランスよく同時に拡大していく考え方はどれか。EfficientNetで採用された。',
   NULL::text,
   '["複合スケーリング（Compound Scaling）", "データ拡張（Data Augmentation）", "転移学習（Transfer Learning）", "ドロップアウト（Dropout）"]',
   0, '[0]', 'single',
   '{"asked":"深さ・幅・解像度をバランスよく同時に拡大する考え方を選ぶ問題。","why_asked":"モデルを大きくする際に「どこか1つだけ増やす」のではなく「バランス良く増やす」という発想の転換をEfficientNetの文脈で問う。","kid":"モデルの性能を上げたいとき、「層をひたすら深くする」「チャネル数をひたすら増やす」「画像を高解像度にする」のどれか1つだけをやりすぎると、効率が悪くなってしまうことが分かっている。複合スケーリングは、深さ・幅・解像度の3つを、決めた比率を守りながら一緒に少しずつ増やしていくことで、無駄なく性能を伸ばす考え方。","eg":"たとえるなら、料理のレシピを2倍にするとき、具材だけを2倍にして味付けや火加減をそのままにすると美味しくならないので、具材・調味料・火加減のすべてをバランスよく同時に調整する、というイメージ。","terms":[["複合スケーリング","深さ・幅・解像度の3つを、一定の比率を保ちながら同時に拡大する考え方"],["EfficientNet","複合スケーリングによって効率よく精度を上げた画像認識モデルの系列"]],"think":"「1つだけ増やすと非効率」「3つをバランスよく同時に」という組み合わせが複合スケーリングを見分ける決め手。深さだけを増やすと勾配消失が起きやすくなり、幅だけを増やすと細かい特徴を捉えにくくなり、解像度だけを上げても層が浅いと活かしきれない、という3者の兼ね合いを踏まえた設計になっている。","vs":"転移学習と混同しやすいが、転移学習はすでに学習済みのモデルを別のタスクに再利用する手法で、モデルの深さ・幅・解像度を拡大する複合スケーリングとは別の概念。","opt":["正解。深さ・幅・解像度の3つを一定の比率でバランスよく同時に拡大する考え方。","データ拡張は画像の回転や反転などでデータを水増しする手法で、モデルの構造の拡大とは異なる。","転移学習は学習済みモデルを別のタスクに再利用する手法で、深さ・幅・解像度の拡大とは異なる概念。","ドロップアウトは学習時に一部のノードを無効化する過学習対策で、モデルの構造の拡大とは異なる。"]}'),

  ('g-kentei-j-q36', '5. ディープラーニングの要素技術',
   '1つの大きなネットワークの代わりに、複数の「専門家」となる小さなネットワークを用意しておき、入力ごとにその一部だけを選んで使うことで、計算量を抑えながらモデル全体の規模を大きくできる仕組みはどれか。',
   NULL::text,
   '["Mixture of Experts（MoE）", "アンサンブル学習", "ドロップアウト", "バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"複数の専門家ネットワークを用意し入力ごとに一部だけ使う仕組みを選ぶ問題。","why_asked":"近年の大規模言語モデルでも採用が増えている「疎に活性化する」大規模モデルの代表的な設計を押さえているか問う。","kid":"MoEは、1つの巨大なネットワークがすべての仕事を1人でこなすのではなく、いろいろな「得意分野を持つ専門家（小さなネットワーク）」を何人も用意しておき、入力の内容に応じて「今回はこの専門家たちに任せよう」と一部だけを選んで使う仕組み。専門家全員を毎回使うわけではないので、モデル全体は巨大でも、1回の計算量は抑えられる。","eg":"たとえるなら、病院に内科・外科・皮膚科などたくさんの専門医（専門家ネットワーク）がいても、患者（入力）ごとに必要な専門医だけを選んで診察してもらう、というイメージ。全員が毎回全患者を診るわけではない。","terms":[["Mixture of Experts（MoE）","複数の専門家ネットワークを用意し、入力ごとに一部だけを選んで使う仕組み"],["アンサンブル学習","複数のモデルの予測結果を組み合わせて、より良い予測を作る手法（全モデルを毎回使う点がMoEと異なる）"]],"think":"「複数の専門家を用意する」「入力ごとに一部だけ使う」という2点がMoEを見分ける決め手。似たアンサンブル学習は複数のモデルを組み合わせるが、基本的にすべてのモデルの予測を毎回使う点で、一部だけを選択的に使うMoEとは異なる。","vs":"アンサンブル学習と混同しやすいが、アンサンブル学習は複数モデルの結果を毎回すべて組み合わせるのに対し、MoEは入力ごとに一部の専門家だけを選んで使う点が違う。","opt":["正解。複数の専門家ネットワークを用意し、入力ごとにその一部だけを選んで使う仕組み。","アンサンブル学習は複数モデルの予測結果を毎回すべて組み合わせる手法で、一部だけを選ぶMoEとは異なる。","ドロップアウトは学習時にノードの一部をランダムに無効化する過学習対策で、専門家ネットワークの選択とは異なる。","バッチ正規化は値のばらつきをそろえる正規化手法で、専門家ネットワークの選択とは無関係。"]}'),

  ('g-kentei-j-q37', '5. ディープラーニングの要素技術',
   'ニューロン1つを1つの数値ではなく、物体の姿勢や向きといった情報を含む「ベクトル」として表現し、部分と全体の位置関係をより自然に捉えようとするネットワーク構造はどれか。',
   NULL::text,
   '["Capsule Network（カプセルネットワーク）", "オートエンコーダ", "Siamese Network（シャムネットワーク）", "Highway Network"]',
   0, '[0]', 'single',
   '{"asked":"ニューロンをベクトルとして表現し、部分と全体の位置関係を捉えようとするネットワーク構造を選ぶ問題。","why_asked":"通常のCNNのプーリングが位置情報を失いやすいという弱点への対策案として、発展的な話題ながらG検定で名前が問われることがある論点。","kid":"ふつうのニューラルネットワークのニューロンは「1つの数値」しか持たないけれど、Capsule Networkのニューロン（カプセル）は「向き」や「大きさ」などいくつもの情報をまとめて持つ「ベクトル」になっている。これにより、「目と鼻と口がバラバラの位置にあっても顔だと誤認識してしまう」ような、CNNが苦手とする部分と全体の位置関係の把握を改善しようとしている。","eg":"たとえるなら、ふつうのニューロンは「あるかないか」の1ビットの旗しか立てられないのに対し、カプセルは「向き・大きさ・角度」まで書き込める詳しい伝言メモのようなもの。より豊かな情報を次の層に伝えられる。","terms":[["Capsule Network","ニューロンをベクトルとして表現し、部分と全体の空間的な関係を捉えようとするネットワーク構造"],["ルーティング(routing)","カプセルどうしが、どの上位カプセルに情報を送るべきかを合意形成しながら決める仕組み"]],"think":"「ニューロンがベクトル（複数の情報を持つ）」という点がCapsule Networkの最大の特徴。通常のCNNのプーリングは位置のズレに強くする代わりに正確な位置関係の情報を失いやすいが、Capsule Networkはこの位置関係の情報をベクトルとして保持しようとしている。","vs":"オートエンコーダと混同しやすいが、オートエンコーダは入力を圧縮して復元する構造であり、ニューロンをベクトル化して位置関係を捉える仕組みとは目的も構造も異なる。","opt":["正解。ニューロンをベクトルとして表現し、部分と全体の空間的な関係をより自然に捉えようとするネットワーク構造。","オートエンコーダは入力を低次元に圧縮し復元する構造で、ニューロンのベクトル化による位置関係の把握とは異なる。","Siamese Networkは2つの入力を同じ重みのネットワークに通して類似度を比較する構造で、ニューロンのベクトル化とは異なる話題。","Highway Networkはゲートで素通しと変換を切り替えるスキップ結合の一種で、ニューロンのベクトル化とは異なる仕組み。"]}'),

  ('g-kentei-j-q38', '5. ディープラーニングの要素技術',
   '2つの入力（例えば2枚の顔写真）を、まったく同じ重みを共有する2つのネットワークにそれぞれ通し、出てきた2つの埋め込みベクトルの距離や類似度を比較することで「同じかどうか」を判定する構造はどれか。',
   NULL::text,
   '["Siamese Network（シャムネットワーク）", "オートエンコーダ", "Highway Network", "Capsule Network"]',
   0, '[0]', 'single',
   '{"asked":"重みを共有した2つのネットワークで2つの入力を比較する構造を選ぶ問題。","why_asked":"顔認証や類似画像検索など、Triplet Lossとセットで使われる代表的なネットワーク構造で、重みの共有という特徴を押さえているか問う。","kid":"Siamese Networkは、2枚の写真を「まったく同じ性格の双子（同じ重みを持つ2つのネットワーク）」にそれぞれ見てもらい、それぞれが出した感想（埋め込みベクトル）がどれだけ似ているかを比べることで、「この2枚は同じ人物か違う人物か」を判定する仕組み。双子は同じ基準で見ているので、比較がフェアになる。","eg":"たとえるなら、2枚の写真を「まったく同じ採点基準を持つ2人の審査員（実は同一人物の分身）」にそれぞれ採点してもらい、その採点結果がどれだけ近いかで「同じ人物かどうか」を判定するイメージ。","terms":[["Siamese Network","重みを共有した2つのネットワークに2つの入力を通し、出力の類似度を比較する構造"],["重みの共有","2つ（またはそれ以上）のネットワークが、まったく同じ重みの値を使うこと"]],"think":"「重みを共有した2つのネットワーク」「類似度の比較」という組み合わせがSiamese Networkを見分ける決め手。重みを共有しているからこそ、2つの入力は同じ基準（同じ変換のルール）で埋め込みベクトルに変換され、その距離を公平に比較できる。","vs":"Triplet Lossと混同しやすいが、Triplet Lossは学習に使う誤差関数の名前であり、Siamese Networkはその学習に使われるネットワークの構造そのものを指す、役割の異なる概念。","opt":["正解。重みを共有した2つのネットワークに2つの入力をそれぞれ通し、出力の類似度を比較する構造。","オートエンコーダは1つの入力を圧縮して復元する構造で、2つの入力を比較する仕組みではない。","Highway Networkはゲートで素通しと変換を切り替えるスキップ結合の一種で、重みを共有した2系統の比較とは異なる。","Capsule Networkはニューロンをベクトルとして表現する構造で、重みを共有した2つのネットワークによる比較とは異なる話題。"]}'),

  ('g-kentei-j-q39', '5. ディープラーニングの要素技術',
   'レイヤー正規化(LayerNorm)から、平均を引いて中心をそろえる処理を省略し、値のばらつき（大きさ）の調整だけを行うことで計算を軽くした正規化手法はどれか。',
   NULL::text,
   '["RMSNorm", "バッチ正規化", "インスタンス正規化", "グループ正規化"]',
   0, '[0]', 'single',
   '{"asked":"レイヤー正規化から平均を引く処理を省いて軽量化した正規化手法を選ぶ問題。","why_asked":"大規模言語モデルの内部でLayerNormの代わりに使われることが増えている、比較的新しい軽量化の工夫。","kid":"レイヤー正規化は「平均を引いて中心をそろえる」処理と「ばらつきの大きさをそろえる」処理の2つをセットで行う。RMSNormは、このうち「平均を引く」処理を省略して、「ばらつきの大きさをそろえる」処理だけを行うことで、計算をシンプルにして軽くしたもの。","eg":"たとえるなら、テストの点数を「平均点との差」と「ばらつきの大きさ」の両方で調整する採点方法から、「平均点との差」の調整を省いて「ばらつきの大きさ」の調整だけにする、簡略版の採点方法のようなイメージ。","terms":[["RMSNorm","レイヤー正規化から平均を引く処理を省き、値の大きさ（二乗平均平方根）だけをそろえる軽量な正規化手法"],["レイヤー正規化(LayerNorm)","1つのサンプルの中の特徴どうしをそろえて正規化する手法。平均を引く処理とばらつきをそろえる処理の両方を行う"]],"think":"「平均を引く処理を省く」という一点がRMSNormの特徴。レイヤー正規化の2段階の処理（平均をそろえる、ばらつきをそろえる）のうち、計算コストのかかる平均を引く処理を省略しても実用上は十分な効果が得られる、という発見に基づいている。","vs":"レイヤー正規化と混同しやすいが、レイヤー正規化は平均を引く処理とばらつきをそろえる処理の両方を行うのに対し、RMSNormは平均を引く処理を省く点が違う。","opt":["正解。レイヤー正規化から平均を引く処理を省き、ばらつきの大きさの調整だけを行う軽量な正規化手法。","バッチ正規化はミニバッチ内でそろえる正規化手法で、平均を引く処理を省略した軽量版という説明には当てはまらない。","インスタンス正規化は1枚の画像の1チャネルの中でそろえる正規化手法で、平均を引く処理の省略とは異なる特徴を持つ。","グループ正規化はチャネルをいくつかのグループに分けてそろえる正規化手法で、平均を引く処理の省略とは異なる特徴を持つ。"]}'),

  ('g-kentei-j-q40', '5. ディープラーニングの要素技術',
   'Transformerの各層で、正規化層(LayerNorm)をAttentionやフィードフォワード層の「前」に置くPre-LNという構成は、「後」に置くPost-LNという構成と比べて、どのような利点があるとされるか。',
   NULL::text,
   '["層をより深く積み重ねても、勾配が安定しやすく学習が発散しにくい", "計算に使うメモリの量が常に半分になる", "パラメータの数が常に半分になる", "正規化そのものが不要になり、正規化層を完全に取り除ける"]',
   0, '[0]', 'single',
   '{"asked":"Pre-LNがPost-LNと比べて持つとされる利点を選ぶ問題。","why_asked":"Transformerの内部構成の細部として、正規化層を置く位置による学習の安定性の違いを押さえているか問う発展的論点。","kid":"Post-LNは「Attentionやフィードフォワードの計算をしてから最後に正規化する」順番。Pre-LNは「先に正規化してから計算する」順番。Pre-LNの方が、層をたくさん重ねても勾配が安定して伝わりやすく、学習の初期段階で発散しにくいことが分かっている。","eg":"たとえるなら、Post-LNは「料理を作ってから最後に味を整える」やり方。Pre-LNは「先に材料の状態を整えてから料理する」やり方。先に整えておく方が、工程をたくさん重ねても味（勾配）が安定しやすい、というイメージ。","terms":[["Pre-LN","正規化層をAttentionやフィードフォワード層の「前」に置くTransformerの構成"],["Post-LN","正規化層をAttentionやフィードフォワード層の「後」に置く、元々のTransformerの構成"]],"think":"「正規化を先にするか後にするか」という順番の違いが学習の安定性に影響する、という因果関係を押さえる。Pre-LNは各層に入る前に値を整えておくため、層を深く重ねたときに勾配が極端に大きくなったり小さくなったりしにくく、学習率のウォームアップなしでも比較的安定して学習できるとされる。","vs":"「正規化の位置を変えても効果は同じ」という誤解に注意。同じ正規化層を使っていても、計算の前に置くか後に置くかで、深いネットワークでの学習の安定性が変わってくる。","opt":["正解。層をより深く積み重ねても勾配が安定しやすく、学習が発散しにくいという利点があるとされる。","正規化層を置く位置を変えるだけでは、メモリ使用量が半分になるという効果は生まれない。","正規化層を置く位置を変えるだけでは、パラメータ数が半分になるという効果は生まれない。","Pre-LNも正規化層自体は使っており、正規化そのものをなくす構成ではない。"]}'),

  ('g-kentei-j-q41', '5. ディープラーニングの要素技術',
   'BERTのように入力全体を読んで文脈を理解することに特化したEncoder-onlyのTransformer、GPTのように次に来る単語を1つずつ予測して文章を生成することに特化したDecoder-onlyのTransformer、そして翻訳のように入力を別の系列に変換するEncoder-Decoder型のTransformer。この3つの型の使い分けの説明として最も適切なものはどれか。',
   NULL::text,
   '["文章の理解や分類にはEncoder-only、文章の生成にはDecoder-only、系列変換にはEncoder-Decoderが向いているとされる", "3つの型はすべて内部構造も得意なタスクも同じであり、名前が違うだけで実質的な差はない", "Encoder-onlyは文章生成にのみ使われ、Decoder-onlyは文章の理解にのみ使われる", "Encoder-Decoder型は入力を必要とせず、出力だけを生成する構造である"]',
   0, '[0]', 'single',
   '{"asked":"Encoder-only・Decoder-only・Encoder-Decoderという3つのTransformerの型の使い分けを問う問題。","why_asked":"BERTとGPTを「両方ともTransformer」とひとくくりにせず、内部構造の型の違いから得意なタスクを説明できるかを問う。","kid":"Encoder-onlyは「文章全体を一気に読んで理解する」のが得意で、文章の分類や意味の把握に向いている（BERTなど）。Decoder-onlyは「これまで書いた文章の続きを1語ずつ予測して書き足していく」のが得意で、文章生成に向いている（GPTなど）。Encoder-Decoder型は「一度読んで理解してから、別の文章として書き出す」翻訳のようなタスクに向いている。","eg":"たとえるなら、Encoder-onlyは「文章を読んで内容を要約するのが得意な読解の専門家」、Decoder-onlyは「お題から続きの物語をどんどん書き足していくのが得意な作家」、Encoder-Decoder型は「原文を読んでから別の言語に訳す通訳者」というイメージ。","terms":[["Encoder-only","入力全体を読んで理解する処理に特化したTransformerの型。BERTなど"],["Decoder-only","次の単語を順番に予測して生成する処理に特化したTransformerの型。GPTなど"],["Encoder-Decoder","入力を読み取る部分と、別の系列を生成する部分を両方持つTransformerの型。翻訳などに使われる"]],"think":"「読んで理解するだけ」「生成し続けるだけ」「読んでから別のものを生成する」という3つのタスクの性質に対応させて覚える。BERT系は分類・理解タスクの前処理として使われることが多く、GPT系は文章生成、翻訳などの系列変換タスクにはEncoder-Decoder型が使われることが多い、という対応関係がある。","vs":"「TransformerはすべてAttentionを使うから同じ」という理解にとどまると3つの型の違いを見落としやすいが、Attentionの使い方（自己注意だけか、Encoder-Decoder間の注意も使うか）と処理の向き（双方向か、次を予測する方向だけか）が型ごとに異なる。","opt":["正解。理解や分類にはEncoder-only、生成にはDecoder-only、系列変換にはEncoder-Decoderが向いているとされる。","3つの型は内部の注意の使い方や処理の向きが異なり、得意なタスクにも違いがあるとされる。","Encoder-onlyとDecoder-onlyの説明が入れ替わっており、実際の得意分野とは逆になっている。","Encoder-Decoder型は入力を読み取るEncoder部分を持ち、入力を必要としない構造ではない。"]}'),

  ('g-kentei-j-q42', '5. ディープラーニングの要素技術',
   'VQ-VAEのように、勾配を計算できない離散的な演算（例えば「最も近い符号を選ぶ」という処理）を含むネットワークで、逆伝播のときだけその演算をあたかも素通りしたかのように扱い、勾配をそのまま後ろの層へ伝えるトリックを何と呼ぶか。',
   NULL::text,
   '["Straight-Through Estimator", "バッチ正規化", "重み減衰", "アーリーストッピング"]',
   0, '[0]', 'single',
   '{"asked":"離散的な演算の逆伝播で勾配をそのまま通すトリックの名前を選ぶ問題。","why_asked":"VQ-VAEのような離散表現を使うモデルの学習で欠かせない工夫で、「なぜ普通の逆伝播では学習できないのか」を理解しているか問う。","kid":"「一番近い符号を選ぶ」ような処理は、途中で値がカクッと飛び変わるだけで、なめらかな傾き（勾配）が存在しない。このままでは逆伝播で勾配を計算できず、手前の層まで学習の合図が届かない。Straight-Through Estimatorは、「順伝播ではその処理をそのまま行うが、逆伝播のときだけ、まるでその処理が無かったかのように勾配をそのまま素通りさせる」という便宜的なトリックで、学習を成り立たせる。","eg":"たとえるなら、途中に「くじ引きで1つだけ選ぶ」という工程があるゲームで、順番にプレイするときはちゃんとくじ引きをするけれど、後から成績を振り返る（逆伝播する）ときだけは「くじ引きの工程は無かったことにして、そのまま得点を持ち越す」というルールにするイメージ。","terms":[["Straight-Through Estimator","離散的で勾配を計算できない演算を、逆伝播のときだけ素通りしたものとみなして勾配を伝えるトリック"],["VQ-VAE","連続値ではなく、あらかじめ用意した符号帳から最も近い符号を選ぶ離散的な潜在変数を使うオートエンコーダの一種"]],"think":"「離散的な演算には勾配が存在しない」という問題点と、「逆伝播のときだけ素通りとみなす」という対策をセットで覚える。順伝播（実際の計算）と逆伝播（勾配の計算）で扱いを変える、という便宜的な工夫である点がポイント。","vs":"Gumbel-Softmaxと混同しやすいが、Gumbel-Softmaxは離散的なサンプリングそのものを連続値のなめらかな近似に置き換えるのに対し、Straight-Through Estimatorは離散演算自体は残したまま逆伝播だけ勾配を素通りさせる点が違う。","opt":["正解。離散的で勾配を計算できない演算を、逆伝播のときだけ素通りしたとみなして勾配を伝えるトリック。","バッチ正規化は値のばらつきをそろえる正規化手法で、離散演算の逆伝播の問題とは無関係。","重み減衰は重みの大きさにペナルティを課す正則化手法で、離散演算の逆伝播の問題とは無関係。","アーリーストッピングは検証誤差の悪化を見て学習を打ち切る過学習対策で、離散演算の逆伝播の問題とは無関係。"]}'),

  ('g-kentei-j-q43', '5. ディープラーニングの要素技術',
   '離散的なカテゴリからのサンプリング（例えばサイコロを振ってどの目が出るか選ぶような処理）を、勾配が計算できる連続的な値でなめらかに近似することで、逆伝播による学習を可能にする手法はどれか。',
   NULL::text,
   '["Gumbel-Softmax", "Straight-Through Estimator", "バッチ正規化", "ラベルスムージング"]',
   0, '[0]', 'single',
   '{"asked":"離散的なサンプリングを連続的な値で近似して微分可能にする手法を選ぶ問題。","why_asked":"Straight-Through Estimatorと並んで、離散的な選択を含むモデルの学習でよく使われる代表的な工夫で、両者の違いを区別できるか問う。","kid":"サイコロを振って「1〜6のどれかを選ぶ」ような処理は、選んだ瞬間にカクッと1つの目に決まってしまい、なめらかな傾き（勾配）を計算できない。Gumbel-Softmaxは、このサイコロを振る処理を「なめらかに変化する確率の山」で近似することで、勾配を計算できるようにする工夫。温度というつまみを調整すると、なめらかさの度合いを変えられる。","eg":"たとえるなら、サイコロを振って1つの目に決める代わりに、6つの目それぞれに「今回はこのくらいそれっぽい」という、なめらかに変化する度合いを割り振っておくイメージ。カクッと1つに決め切らないので、微調整（勾配計算）がしやすい。","terms":[["Gumbel-Softmax","離散的なサンプリングを、勾配計算が可能ななめらかな連続値で近似する手法"],["温度パラメータ","Gumbel-Softmaxのなめらかさの度合いを調整するパラメータ。小さくするほど元の離散的な選択に近づく"]],"think":"「サンプリングそのものをなめらかに近似する」という点がGumbel-Softmaxの特徴。似た目的のStraight-Through Estimatorは離散的な演算自体は残したまま逆伝播だけ工夫するのに対し、Gumbel-Softmaxは順伝播の段階から連続的な近似に置き換えている点で発想が異なる。","vs":"Straight-Through Estimatorと混同しやすいが、Straight-Through Estimatorは離散演算をそのまま行い逆伝播だけ素通りさせるのに対し、Gumbel-Softmaxは順伝播の時点でサンプリング自体をなめらかな連続値に近似する点が違う。","opt":["正解。離散的なサンプリングを、勾配計算が可能ななめらかな連続値で近似する手法。","Straight-Through Estimatorは離散演算自体は残したまま逆伝播のときだけ勾配を素通りさせる手法で、順伝播からなめらかに近似するGumbel-Softmaxとは異なる。","バッチ正規化は値のばらつきをそろえる正規化手法で、離散的なサンプリングの近似とは無関係。","ラベルスムージングは正解ラベルの値を緩める工夫で、離散的なサンプリングの近似とは無関係。"]}'),

  ('g-kentei-j-q44', '4. ディープラーニングの概要',
   'ニューラルネットワークの層を、離散的に積み重なった有限個のブロックとしてではなく、入力が連続的に少しずつ変化していく「常微分方程式」に従う滑らかな変換とみなす考え方はどれか。',
   NULL::text,
   '["Neural ODE（ニューラル常微分方程式）", "残差接続（スキップ結合）", "バッチ正規化", "ドロップアウト"]',
   0, '[0]', 'single',
   '{"asked":"層を連続的な常微分方程式として捉える考え方を選ぶ問題。","why_asked":"「層を積み重ねる」という離散的な発想を、連続的な変換として捉え直す発展的な視点を知っているか問う。","kid":"ふつうのニューラルネットワークは「1層、2層、3層…」と区切られた階段のような構造をしている。Neural ODEは、この階段を「なめらかに続く坂道」とみなし、層を区切って積み重ねる代わりに、入力が連続的にじわじわ変化していく様子を数式（常微分方程式）で表現する考え方。","eg":"たとえるなら、ふつうのネットワークは「1段ずつ上る階段」。Neural ODEは、その階段を「なめらかなスロープ」に置き換えて、途中の高さも自由に取り出せるようにするイメージ。","terms":[["Neural ODE","層を離散的な積み重ねではなく、連続的に変化する常微分方程式とみなす考え方"],["常微分方程式(ODE)","ある値が時間や位置に応じてどう変化していくかを表す数式"]],"think":"「層を区切らず連続的に変化するものとして捉える」という発想の転換がNeural ODEの核心。層の数を固定するのではなく、変化の速さを表す方程式を1つ用意し、それをどこまで進めるかで「実質的な層の深さ」を柔軟に変えられる、という利点がある。","vs":"残差接続（スキップ結合）と混同しやすいが、残差接続は離散的な層の間を飛び越える近道を追加する仕組みであり、層そのものを連続的な方程式として捉え直すNeural ODEとは発想の出発点が異なる。","opt":["正解。層を離散的な積み重ねではなく、連続的に変化する常微分方程式とみなす考え方。","残差接続は離散的な層の間にショートカットを追加する仕組みで、層を連続的な方程式とみなす考え方そのものではない。","バッチ正規化は値のばらつきをそろえる正規化手法で、層を連続的に捉える考え方とは無関係。","ドロップアウトは学習時にノードの一部を無効化する過学習対策で、層を連続的に捉える考え方とは無関係。"]}'),

  ('g-kentei-j-q45', '5. ディープラーニングの要素技術',
   '入力ノードが40個、出力ノードが10個の全結合層がある。各出力ノードにバイアスが1つずつ付くとすると、この全結合層が持つ重みとバイアスを合わせたパラメータの総数はいくつになるか。',
   NULL::text,
   '["410", "400", "50", "440"]',
   0, '[0]', 'single',
   '{"asked":"全結合層の入力数と出力数からパラメータの総数を計算する問題。","why_asked":"全結合層のパラメータ数を「重みの数」と「バイアスの数」に分けて数えられるかを試す基本の計算問題。","kid":"全結合層は、入力のすべてのノードと出力のすべてのノードが1本ずつ線（重み）でつながっている。だから重みの数は「入力の数×出力の数」で求まる。さらに、出力ノード1つにつきバイアスが1個ずつ付くので、バイアスの数は「出力の数」と同じになる。最後にこの2つを足し合わせる。","eg":"たとえるなら、40人の生徒（入力）と10人の先生（出力）が、全員と全員で1本ずつ電話線（重み）を引くと40×10=400本。さらに先生10人それぞれに専用の内線番号（バイアス）を1つずつ持たせると10個追加。合計は400+10=410。","terms":[["全結合層","前の層のすべてのノードと、次の層のすべてのノードを1本ずつの重みでつなぐ層"],["バイアス","各出力ノードに1つずつ加えられる、入力に依存しない調整用のパラメータ"]],"calc":{"steps":["問題: 入力ノード40個、出力ノード10個の全結合層のパラメータ総数を求める","ステップ1: 重みの数を計算する。入力の数×出力の数 = 40 × 10 = 400","ステップ2: バイアスの数を計算する。出力ノード1つにつき1個なので、10個","ステップ3: 重みとバイアスを合計する。400 + 10 = 410","答え: パラメータの総数は410"],"formula":"パラメータ数 = (入力数 × 出力数) + 出力数 = (40×10) + 10 = 400 + 10 = 410"},"think":"全結合層のパラメータ数は「重み（入力数×出力数）」と「バイアス（出力数と同じ数）」の2つに分けて計算し、最後に足し合わせるという手順を守れば、掛け算と足し算だけで求められる。","vs":"バイアスを数え忘れて「400」とだけ答えてしまう間違いに注意。全結合層のパラメータには重みだけでなく、出力ノードごとのバイアスも含まれる。","opt":["正解。重み400個(40×10)とバイアス10個(出力数)を合計して410。","バイアスの数を数え忘れ、重みの数(40×10=400)だけを答えてしまった場合の値。","入力数と出力数を掛け算せず、単純に足し算(40+10=50)してしまった場合の値。","バイアスを出力数の10個ではなく入力数の40個ぶん余分に足してしまった場合の値(400+40=440)。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-j'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
